import React, { useState, useEffect, useMemo } from 'react';
import { createRoot } from 'react-dom/client';

// --- TYPES & ENUMS ---

enum VehicleType {
  PKW = 'PKW',
  LKW = 'LKW',
  AUFLIEGER = 'Auflieger',
  ANHAENGER = 'Anhänger',
  MASCHINE = 'Maschine',
}

enum EntryType {
  REPARATUR = 'Reparatur',
  WARTUNG = 'Wartung',
  PRUEFUNG = 'Prüfung',
}

enum OrderStatus {
  OFFEN = 'Offen',
  BESTELLT = 'Bestellt',
  ERLEDIGT = 'Erledigt',
}

interface Vehicle {
  id: string;
  licensePlate: string;
  type: VehicleType;
  manufacturer: string;
  model: string; // Typ
  vin: string;
  year: number;
  notes: string;
  coupledVehicleId?: string | null; // For LKW <-> Auflieger

  // Inspection Due Dates (MM/YYYY)
  nextHU?: string;
  nextSP?: string;
  nextUVV?: string;
  nextTacho?: string;

  currentMileage?: number; // KM or Hours
}

interface LogEntry {
  id: string;
  vehicleId: string;
  type: EntryType;
  description: string;
  dateAdded: string; // ISO Date
  dateCompleted?: string;
  status: 'OPEN' | 'DONE';
  mileage?: number;

  // Specific for inspections
  inspectionType?: 'HU' | 'SP' | 'UVV' | 'Tacho';
}

interface Order {
  id: string;
  description: string;
  vehicleId?: string;
  dateAdded: string;
  status: OrderStatus;
}

// --- ICONS ---

const Icons = {
  Dashboard: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect width="7" height="9" x="3" y="3" rx="1" /><rect width="7" height="5" x="14" y="3" rx="1" /><rect width="7" height="9" x="14" y="12" rx="1" /><rect width="7" height="5" x="3" y="16" rx="1" /></svg>,
  Truck: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M10 17h4V5H2v12h3"/><path d="M20 17h2v-3.34a4 4 0 0 0-1.17-2.83L19 9h-5"/><path d="M14 17h1"/><circle cx="7.5" cy="17.5" r="2.5"/><circle cx="17.5" cy="17.5" r="2.5"/></svg>,
  Calendar: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect width="18" height="18" x="3" y="4" rx="2" ry="2" /><line x1="16" x2="16" y1="2" y2="6" /><line x1="8" x2="8" y1="2" y2="6" /><line x1="3" x2="21" y1="10" y2="10" /></svg>,
  History: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 12" /><path d="M3 3v9h9" /><path d="M12 7v5l4 2" /></svg>,
  ShoppingCart: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="8" cy="21" r="1" /><circle cx="19" cy="21" r="1" /><path d="M2.05 2.05h2l2.66 12.42a2 2 0 0 0 2 1.58h9.78a2 2 0 0 0 1.95-1.57l1.65-7.43H5.12" /></svg>,
  Plus: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14"/><path d="M12 5v14"/></svg>,
  Trash: () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"/></svg>,
  Edit: () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/><path d="m15 5 4 4"/></svg>,
  Check: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>,
  Lock: () => <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect width="18" height="11" x="3" y="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>,
  Printer: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect width="12" height="8" x="6" y="14"/></svg>,
  Filter: () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/></svg>
};

// --- HELPER FUNCTIONS ---

const generateId = () => Math.random().toString(36).substr(2, 9);
const getTodayDate = () => new Date().toISOString().split('T')[0];

const isValidDateMMYYYY = (val: string) => /^\d{2}\/\d{4}$/.test(val);

const compareDatesMMYYYY = (a: string, b: string) => {
  if (!a) return 1;
  if (!b) return -1;
  const [ma, ya] = a.split('/').map(Number);
  const [mb, yb] = b.split('/').map(Number);
  if (ya !== yb) return ya - yb;
  return ma - mb;
};

// --- HOOKS ---

function usePersistentState<T>(key: string, initialValue: T) {
  const [state, setState] = useState<T>(() => {
    try {
      const item = localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.error(error);
      return initialValue;
    }
  });

  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(state));
  }, [key, state]);

  return [state, setState] as const;
}

// --- MAIN APPLICATION ---

const App = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [vehicles, setVehicles] = usePersistentState<Vehicle[]>('mfm_vehicles', []);
  const [logs, setLogs] = usePersistentState<LogEntry[]>('mfm_logs', []);
  const [orders, setOrders] = usePersistentState<Order[]>('mfm_orders', []);

  // Admin Mode
  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');

  // Modals
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [editingVehicle, setEditingVehicle] = useState<Vehicle | null>(null);

  const [showEntryModal, setShowEntryModal] = useState(false);
  const [editingEntry, setEditingEntry] = useState<LogEntry | null>(null);

  const [showOrderModal, setShowOrderModal] = useState(false);

  const [showInspectionCompleteModal, setShowInspectionCompleteModal] = useState(false);
  const [completingInspection, setCompletingInspection] = useState<{entry: LogEntry, newDate: string} | null>(null);

  const handleAdminLogin = () => {
    if (adminPassword === 'Co33ing#admin') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setAdminPassword('');
    } else {
      alert('Falsches Passwort!');
    }
  };

  // --- LOGIC: VEHICLE COUPLING ---
  const handleSaveVehicle = (v: Vehicle) => {
    // Check coupling logic
    if (v.type === VehicleType.LKW && v.coupledVehicleId) {
      // Find if this trailer is coupled to anyone else
      const existingCoupling = vehicles.find(
        other => other.id !== v.id && other.type === VehicleType.LKW && other.coupledVehicleId === v.coupledVehicleId
      );

      if (existingCoupling) {
        const confirm = window.confirm(`Der Auflieger ist bereits mit ${existingCoupling.licensePlate} gekoppelt. Verbindung lösen und neu zuordnen?`);
        if (!confirm) return;

        // Remove old coupling
        setVehicles(prev => prev.map(x => x.id === existingCoupling.id ? { ...x, coupledVehicleId: null } : x));
      }
    }

    if (editingVehicle) {
      setVehicles(prev => prev.map(x => x.id === v.id ? v : x));
    } else {
      setVehicles(prev => [...prev, { ...v, id: generateId() }]);
    }
    setShowVehicleModal(false);
    setEditingVehicle(null);
  };

  const deleteVehicle = (id: string) => {
    if (confirm('Fahrzeug wirklich löschen? Alle Historien bleiben erhalten.')) {
      setVehicles(prev => prev.filter(v => v.id !== id));
    }
  };

  // --- LOGIC: ENTRIES ---
  const handleSaveEntry = (entry: LogEntry) => {
    if (editingEntry) {
      setLogs(prev => prev.map(x => x.id === entry.id ? entry : x));
    } else {
      setLogs(prev => [...prev, { ...entry, id: generateId(), status: 'OPEN', dateAdded: getTodayDate() }]);
    }
    setShowEntryModal(false);
    setEditingEntry(null);
  };

  const handleCompleteEntry = (entry: LogEntry) => {
    if (entry.type === EntryType.PRUEFUNG && entry.inspectionType) {
      setCompletingInspection({ entry, newDate: '' });
      setShowInspectionCompleteModal(true);
    } else {
      setLogs(prev => prev.map(x => x.id === entry.id ? { ...x, status: 'DONE', dateCompleted: getTodayDate() } : x));
    }
  };

  const confirmInspectionCompletion = () => {
    if (!completingInspection || !isValidDateMMYYYY(completingInspection.newDate)) {
      alert('Bitte gültiges Datum im Format MM/YYYY eingeben.');
      return;
    }

    const { entry, newDate } = completingInspection;

    // Update Vehicle
    setVehicles(prev => prev.map(v => {
      if (v.id === entry.vehicleId) {
        const update: any = {};
        if (entry.inspectionType === 'HU') update.nextHU = newDate;
        if (entry.inspectionType === 'SP') update.nextSP = newDate;
        if (entry.inspectionType === 'UVV') update.nextUVV = newDate;
        if (entry.inspectionType === 'Tacho') update.nextTacho = newDate;
        return { ...v, ...update };
      }
      return v;
    }));

    // Update Log
    setLogs(prev => prev.map(x => x.id === entry.id ? { ...x, status: 'DONE', dateCompleted: getTodayDate() } : x));

    setShowInspectionCompleteModal(false);
    setCompletingInspection(null);
  };

  const deleteLog = (id: string) => {
    if (confirm('Eintrag löschen?')) {
      setLogs(prev => prev.filter(x => x.id !== id));
    }
  };

  // --- LOGIC: ORDERS ---
  const handleAddOrder = (order: Order) => {
    setOrders(prev => [...prev, { ...order, id: generateId(), status: OrderStatus.OFFEN, dateAdded: getTodayDate() }]);
    setShowOrderModal(false);
  };

  const updateOrderStatus = (id: string, status: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === id ? { ...o, status } : o));
  };

  const deleteOrder = (id: string) => {
    setOrders(prev => prev.filter(o => o.id !== id));
  }

  // --- RENDER HELPERS ---
  const getVehicleLabel = (vid: string) => {
    const v = vehicles.find(x => x.id === vid);
    if (!v) return 'Unbekannt';
    let label = v.licensePlate;
    // Show coupling
    if (v.type === VehicleType.LKW && v.coupledVehicleId) {
      const coupled = vehicles.find(c => c.id === v.coupledVehicleId);
      if (coupled) label += ` [${coupled.licensePlate}]`;
    }
    return label;
  };

  return (
    <div className="flex h-screen flex-col md:flex-row font-sans">
      {/* SIDEBAR NAVIGATION */}
      <div className="w-full md:w-64 bg-slate-800 text-white flex-shrink-0 flex flex-col no-print">
        <div className="p-4 font-bold text-xl border-b border-slate-700">Fuhrpark Manager</div>
        <nav className="flex-1 p-2 space-y-1">
          {[
            { id: 'dashboard', label: 'Dashboard / ToDo', icon: Icons.Dashboard },
            { id: 'termine', label: 'Prüftermine', icon: Icons.Calendar },
            { id: 'bestellungen', label: 'Bestellliste', icon: Icons.ShoppingCart },
            { id: 'fahrzeuge', label: 'Fahrzeugstamm', icon: Icons.Truck },
            { id: 'historie', label: 'Historie & Suche', icon: Icons.History },
          ].map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded text-left transition-colors ${activeTab === item.id ? 'bg-primary text-white' : 'text-slate-300 hover:bg-slate-700'}`}
            >
              <item.icon />
              {item.label}
            </button>
          ))}
        </nav>
        <div className="p-4 border-t border-slate-700 text-xs text-slate-500 flex justify-between items-center">
          <span>v1.0 Offline</span>
          <button onClick={() => setShowAdminLogin(true)} className="opacity-50 hover:opacity-100">
            <Icons.Lock />
          </button>
        </div>
      </div>

      {/* MAIN CONTENT AREA */}
      <main className="flex-1 overflow-auto bg-gray-50 p-4 md:p-8 relative">

        {/* --- DASHBOARD --- */}
        {activeTab === 'dashboard' && (
          <DashboardView 
            logs={logs} 
            vehicles={vehicles} 
            onComplete={handleCompleteEntry}
            onEdit={(l) => { setEditingEntry(l); setShowEntryModal(true); }}
            onDelete={deleteLog}
            onAdd={() => { setEditingEntry(null); setShowEntryModal(true); }}
          />
        )}

        {/* --- FAHRZEUGE --- */}
        {activeTab === 'fahrzeuge' && (
          <VehicleListView 
            vehicles={vehicles} 
            onEdit={(v) => { setEditingVehicle(v); setShowVehicleModal(true); }}
            onDelete={deleteVehicle}
            onAdd={() => { setEditingVehicle(null); setShowVehicleModal(true); }}
          />
        )}

        {/* --- TERMINE --- */}
        {activeTab === 'termine' && (
          <AppointmentsView vehicles={vehicles} />
        )}

        {/* --- BESTELLUNGEN --- */}
        {activeTab === 'bestellungen' && (
          <OrdersView 
            orders={orders} 
            vehicles={vehicles}
            onAdd={() => setShowOrderModal(true)}
            onStatusChange={updateOrderStatus}
            onDelete={deleteOrder}
          />
        )}

        {/* --- HISTORIE --- */}
        {activeTab === 'historie' && (
          <HistoryView 
            logs={logs} 
            vehicles={vehicles} 
            isAdmin={isAdmin}
            onEdit={(l) => { setEditingEntry(l); setShowEntryModal(true); }}
            onDelete={deleteLog}
          />
        )}

      </main>

      {/* --- MODALS --- */}

      {/* Vehicle Modal */}
      {showVehicleModal && (
        <VehicleModal 
          isOpen={showVehicleModal} 
          onClose={() => setShowVehicleModal(false)}
          vehicle={editingVehicle}
          allVehicles={vehicles}
          onSave={handleSaveVehicle}
        />
      )}

      {/* Entry Modal */}
      {showEntryModal && (
        <EntryModal 
          isOpen={showEntryModal}
          onClose={() => setShowEntryModal(false)}
          entry={editingEntry}
          vehicles={vehicles}
          onSave={handleSaveEntry}
        />
      )}

      {/* Order Modal */}
      {showOrderModal && (
        <OrderModal
          isOpen={showOrderModal}
          onClose={() => setShowOrderModal(false)}
          vehicles={vehicles}
          onSave={handleAddOrder}
        />
      )}

      {/* Admin Login Modal */}
      {showAdminLogin && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded shadow-lg w-80">
            <h3 className="text-lg font-bold mb-4">Admin Login</h3>
            <input 
              type="password" 
              className="w-full border p-2 rounded mb-4" 
              placeholder="Passwort"
              value={adminPassword}
              onChange={e => setAdminPassword(e.target.value)}
            />
            <div className="flex justify-end gap-2">
              <button onClick={() => setShowAdminLogin(false)} className="px-4 py-2 text-gray-600">Abbrechen</button>
              <button onClick={handleAdminLogin} className="px-4 py-2 bg-primary text-white rounded">Login</button>
            </div>
          </div>
        </div>
      )}

      {/* Inspection Complete Modal */}
      {showInspectionCompleteModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded shadow-lg w-96">
            <h3 className="text-lg font-bold mb-4">Prüfung abgeschlossen</h3>
            <p className="mb-2 text-sm text-gray-600">Bitte neuen Termin für {completingInspection?.entry.inspectionType} eingeben:</p>
            <input 
              type="text" 
              className="w-full border p-2 rounded mb-4" 
              placeholder="MM/YYYY"
              value={completingInspection?.newDate || ''}
              onChange={e => setCompletingInspection(prev => prev ? {...prev, newDate: e.target.value} : null)}
            />
            <div className="flex justify-end gap-2">
              <button onClick={() => setShowInspectionCompleteModal(false)} className="px-4 py-2 text-gray-600">Abbrechen</button>
              <button onClick={confirmInspectionCompletion} className="px-4 py-2 bg-green-600 text-white rounded">Bestätigen & Speichern</button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

// --- SUB-VIEWS ---

const DashboardView = ({ logs, vehicles, onComplete, onEdit, onDelete, onAdd }: any) => {
  const [filterType, setFilterType] = useState('');
  const [filterVehicle, setFilterVehicle] = useState('');
  const [showDone, setShowDone] = useState(false);

  // Auto-generate system alerts for overdue inspections? 
  // For simplicity, we stick to the log list, but ideally, we should inject "virtual" logs for overdue inspections here.
  // The user asked for "ToDo Liste ... gesetzliche Prüfungen ... angezeigt werden".

  // Let's create virtual entries for dashboard from due dates
  const dueInspections = useMemo(() => {
    const alerts: any[] = [];
    vehicles.forEach((v: Vehicle) => {
      const check = (date: string | undefined, type: string) => {
        if (!date) return;
        const [m, y] = date.split('/').map(Number);
        const due = new Date(y, m - 1); // 1st of that month
        const now = new Date();
        // Show if due within next 30 days or overdue
        if (due.getTime() < now.getTime() + 30 * 24 * 60 * 60 * 1000) {
          alerts.push({
            id: `sys_${v.id}_${type}`,
            vehicleId: v.id,
            type: EntryType.PRUEFUNG,
            inspectionType: type,
            description: `Fällige ${type}: ${date}`,
            dateAdded: getTodayDate(),
            status: 'OPEN',
            isSystem: true,
            rawDate: date
          });
        }
      };
      check(v.nextHU, 'HU');
      check(v.nextSP, 'SP');
      check(v.nextUVV, 'UVV');
      check(v.nextTacho, 'Tacho');
    });
    return alerts;
  }, [vehicles]);

  const filteredLogs = [...logs, ...dueInspections].filter((l: any) => {
    if (!showDone && l.status === 'DONE') return false;
    if (showDone && l.status !== 'DONE') return false;
    if (filterType && l.type !== filterType) return false;
    if (filterVehicle && l.vehicleId !== filterVehicle) return false;
    return true;
  }).sort((a, b) => {
    // Sort by license plate
    const vA = vehicles.find((v: any) => v.id === a.vehicleId)?.licensePlate || '';
    const vB = vehicles.find((v: any) => v.id === b.vehicleId)?.licensePlate || '';
    return vA.localeCompare(vB);
  });

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded shadow no-print">
        <h2 className="text-2xl font-bold text-gray-800">Dashboard / ToDo</h2>
        <div className="flex flex-wrap gap-2 items-center">
          <select className="border p-2 rounded" value={filterVehicle} onChange={e => setFilterVehicle(e.target.value)}>
            <option value="">Alle Fahrzeuge</option>
            {vehicles.map((v: any) => <option key={v.id} value={v.id}>{v.licensePlate}</option>)}
          </select>
          <select className="border p-2 rounded" value={filterType} onChange={e => setFilterType(e.target.value)}>
            <option value="">Alle Typen</option>
            {Object.values(EntryType).map(t => <option key={t} value={t}>{t}</option>)}
          </select>
          <label className="flex items-center gap-2 text-sm">
            <input type="checkbox" checked={showDone} onChange={e => setShowDone(e.target.checked)} />
            Erledigte anzeigen
          </label>
          <button onClick={onAdd} className="bg-primary hover:bg-blue-700 text-white px-4 py-2 rounded flex items-center gap-2">
            <Icons.Plus /> Eintrag
          </button>
        </div>
      </div>

      <div className="bg-white rounded shadow overflow-hidden">
        <table className="w-full text-left border-collapse">
          <thead className="bg-gray-100 text-gray-600 uppercase text-sm">
            <tr>
              <th className="p-3">Kennzeichen</th>
              <th className="p-3">Typ</th>
              <th className="p-3">Beschreibung</th>
              <th className="p-3">Datum</th>
              <th className="p-3 text-right">Aktion</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {filteredLogs.length === 0 && (
              <tr><td colSpan={5} className="p-4 text-center text-gray-400">Keine Einträge vorhanden.</td></tr>
            )}
            {filteredLogs.map((l: any) => {
              const vehicle = vehicles.find((v: any) => v.id === l.vehicleId);
              const label = vehicle ? (
                  <span>
                    {vehicle.licensePlate} 
                    {vehicle.type === VehicleType.LKW && vehicle.coupledVehicleId && (
                      <span className="text-xs text-gray-500 ml-1">
                         [{vehicles.find((x:any) => x.id === vehicle.coupledVehicleId)?.licensePlate}]
                      </span>
                    )}
                  </span>
                ) : '???';

              return (
                <tr key={l.id} className={l.isSystem ? 'bg-red-50' : 'hover:bg-gray-50'}>
                  <td className="p-3 font-medium">{label}</td>
                  <td className="p-3">
                    <span className={`px-2 py-1 rounded text-xs text-white ${l.type === EntryType.REPARATUR ? 'bg-red-500' : l.type === EntryType.WARTUNG ? 'bg-orange-500' : 'bg-blue-500'}`}>
                      {l.type}
                    </span>
                    {l.isSystem && <span className="ml-2 text-red-600 text-xs font-bold">AUTOMATISCH</span>}
                  </td>
                  <td className="p-3">{l.description}</td>
                  <td className="p-3 text-sm text-gray-500">{l.dateAdded}</td>
                  <td className="p-3 text-right space-x-2 no-print">
                    {l.status === 'OPEN' && (
                      <>
                        <button 
