enum VehicleType {
  PKW = 'PKW',
  LKW = 'LKW',
  AUFLIEGER = 'Auflieger',
  ANHAENGER = 'Anhänger',
  MASCHINE = 'Maschine',
}

enum EntryType {
  REPARATUR = 'Reparatur',
  WARTUNG = 'Wartung',
  PRUEFUNG = 'Prüfung',
}

enum OrderStatus {
  OFFEN = 'Offen',
  BESTELLT = 'Bestellt',
  ERLEDIGT = 'Erledigt',
