const EntryModal = ({ isOpen, onClose, entry, vehicles, onSave }: any) => {
  const [form, setForm] = useState<Partial<LogEntry>>({
    type: EntryType.REPARATUR,
    vehicleId: vehicles[0]?.id || '',
    description: '',
    status: 'OPEN',
    ...entry
  });

  if (!isOpen) return null;

  const handleSave = (keepOpen: boolean) => {
    onSave(form, keepOpen);
    if (keepOpen) {
      // Reset form for next entry, but keep context (vehicle, etc)
      setForm(prev => ({
        ...prev,
        id: undefined, // Ensure new ID will be generated
        description: '', // Clear description
        mileage: undefined, // Clear mileage
        status: 'OPEN',
        // Keep vehicleId, type, inspectionType
      }));
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded shadow-lg w-full max-w-lg p-6">
