  // Auto-load demo data if empty
  useEffect(() => {
    if (vehicles.length === 0 && logs.length === 0 && orders.length === 0) {
      console.log('Database empty, seeding demo data...');
      setVehicles(DEMO_VEHICLES);
      setLogs(DEMO_LOGS);
      setOrders(DEMO_ORDERS);
    }
  }, [vehicles.length, logs.length, orders.length]);

  const handleAdminLogin = () => {
    if (adminPassword === 'Co33ing#admin') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setAdminPassword('');
    } else {
      alert('Falsches Passwort!');
    }
  };

  // --- LOGIC: VEHICLE COUPLING ---
  const handleSaveVehicle = (v: Vehicle) => {
    // Check coupling logic
    if (v.type === VehicleType.LKW && v.coupledVehicleId) {
      // Find if this trailer is coupled to anyone else
      const existingCoupling = vehicles.find(
        other => other.id !== v.id && other.type === VehicleType.LKW && other.coupledVehicleId === v.coupledVehicleId
      );

      if (existingCoupling) {
        const confirm = window.confirm(`Der Auflieger ist bereits mit ${existingCoupling.licensePlate} gekoppelt. Verbindung lösen und neu zuordnen?`);
        if (!confirm) return;

        // Remove old coupling
        setVehicles(prev => prev.map(x => x.id === existingCoupling.id ? { ...x, coupledVehicleId: null } : x));
      }
    }

    if (editingVehicle) {
      setVehicles(prev => prev.map(x => x.id === v.id ? v : x));
    } else {
      setVehicles(prev => [...prev, { ...v, id: generateId() }]);
    }
    setShowVehicleModal(false);
    setEditingVehicle(null);
  };

  const deleteVehicle = (id: string) => {
    if (confirm('Fahrzeug wirklich löschen? Alle Historien bleiben erhalten.')) {
      setVehicles(prev => prev.filter(v => v.id !== id));
    }
  };

  // --- LOGIC: ENTRIES ---
  const handleSaveEntry = (entry: LogEntry, keepOpen: boolean = false) => {
    if (editingEntry) {
      setLogs(prev => prev.map(x => x.id === entry.id ? entry : x));
    } else {
      setLogs(prev => [...prev, { ...entry, id: generateId(), status: 'OPEN', dateAdded: getTodayDate() }]);
    }

    if (keepOpen) {
      // If we are keeping it open, we are adding another one.
      // If we were in "Edit" mode, we switch to "New" mode context for the next save.
      setEditingEntry(null);
    } else {
      setShowEntryModal(false);
      setEditingEntry(null);
    }
  };

  const handleCompleteEntry = (entry: LogEntry) => {
    if (entry.type === EntryType.PRUEFUNG && entry.inspectionType) {
      setCompletingInspection({ entry, newDate: '' });
      setShowInspectionCompleteModal(true);
    } else {
      setLogs(prev => prev.map(x => x.id === entry.id ? { ...x, status: 'DONE', dateCompleted: getTodayDate() } : x));
    }
  };

  const confirmInspectionCompletion = () => {
    if (!completingInspection || !isValidDateMMYYYY(completingInspection.newDate)) {
      alert('Bitte gültiges Datum im Format MM/YYYY eingeben.');
      return;
    }

    const { entry, newDate } = completingInspection;

    // Update Vehicle
    setVehicles(prev => prev.map(v => {
      if (v.id === entry.vehicleId) {
        const update: any = {};
        if (entry.inspectionType === 'HU') update.nextHU = newDate;
        if (entry.inspectionType === 'SP') update.nextSP = newDate;
        if (entry.inspectionType === 'UVV') update.nextUVV = newDate;
        if (entry.inspectionType === 'Tacho') update.nextTacho = newDate;
        return { ...v, ...update };
      }
      return v;
    }));

    // Update Log
    setLogs(prev => prev.map(x => x.id === entry.id ? { ...x, status: 'DONE', dateCompleted: getTodayDate() } : x));

    setShowInspectionCompleteModal(false);
    setCompletingInspection(null);
  };

  const deleteLog = (id: string) => {
    if (confirm('Eintrag löschen?')) {
      setLogs(prev => prev.filter(x => x.id !== id));
    }
  };

  // --- LOGIC: ORDERS ---
  const handleSaveOrder = (formData: Partial<Order>) => {
    if (editingOrder) {
      setOrders(prev => prev.map(o => o.id === editingOrder.id ? { ...o, ...formData } : o));
    } else {
      setOrders(prev => [...prev, { 
        ...formData, 
        id: generateId(), 
        status: OrderStatus.OFFEN, 
        dateAdded: getTodayDate() 
      } as Order]);
    }
    setShowOrderModal(false);
    setEditingOrder(null);
  };

  const updateOrderStatus = (id: string, status: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === id ? { ...o, status } : o));
  };

  const deleteOrder = (id: string) => {
    if(confirm('Bestellung wirklich löschen?')) {
      setOrders(prev => prev.filter(o => o.id !== id));
    }
