const DatabaseView = ({ db, setDb, refreshData }: any) => {
  const [msg, setMsg] = useState('');

  const exportDB = () => {
    const binaryArray = db.export();
    const blob = new Blob([binaryArray], {type: "application/x-sqlite3"});
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `fuhrpark_${getTodayDate()}.sqlite`;
    a.click();
    window.URL.revokeObjectURL(url);
    setMsg('Datenbank wurde heruntergeladen.');
  };

  const importDB = async (e: any) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const uInt8Array = new Uint8Array(reader.result as ArrayBuffer);
        const SQL = await initSqlJs({ locateFile: file => `https://sql.js.org/dist/${file}` });
        const newDb = new SQL.Database(uInt8Array);
        setDb(newDb);
        // Persist immediately
        const str = uInt8Array.toString();
        localStorage.setItem('mfm_sqlite_db', str);

        // Trigger refresh
        setTimeout(() => {
          window.location.reload(); // Hard reload to ensure clean state
        }, 500);

      } catch (err) {
        console.error(err);
        alert('Fehler beim Laden der Datei. Ist es eine gültige SQLite Datei?');
      }
    };
    reader.readAsArrayBuffer(file);
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded shadow border-l-4 border-orange-500">
        <h2 className="text-2xl font-bold text-gray-800 mb-2">NAS & Mehrbenutzer Synchronisation</h2>
        <p className="text-gray-600 mb-4">
          Da diese App zentral auf einem NAS im Browser läuft, können Daten nicht automatisch auf die Festplatte des Servers geschrieben werden. 
          Um Daten zwischen verschiedenen Nutzern oder Geräten zu teilen, nutzen Sie bitte die Export- und Import-Funktion.
        </p>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-6">
          <div className="border p-4 rounded bg-gray-50">
            <h3 className="font-bold flex items-center gap-2 mb-2"><Icons.Download /> Speichern (Export)</h3>
            <p className="text-sm text-gray-600 mb-3">
              Speichern Sie den aktuellen Stand als <code>.sqlite</code> Datei auf Ihrem NAS-Laufwerk ab, wenn Sie Ihre Arbeit beendet haben.
            </p>
            <button onClick={exportDB} className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 w-full">
              Datenbank herunterladen
            </button>
          </div>

          <div className="border p-4 rounded bg-gray-50">
            <h3 className="font-bold flex items-center gap-2 mb-2"><Icons.Upload /> Laden (Import)</h3>
            <p className="text-sm text-gray-600 mb-3">
              Laden Sie die neueste <code>.sqlite</code> Datei vom NAS, um den aktuellen Stand der Kollegen zu sehen.
            </p>
            <input 
              type="file" 
              onChange={importDB} 
              accept=".sqlite,.db"
              className="block w-full text-sm text-gray-500
                file:mr-4 file:py-2 file:px-4
                file:rounded-full file:border-0
                file:text-sm file:font-semibold
                file:bg-blue-50 file:text-blue-700
                hover:file:bg-blue-100"
            />
          </div>
        </div>
        {msg && <div className="mt-4 text-green-600 font-bold">{msg}</div>}
      </div>

      <div className="bg-white p-6 rounded shadow">
        <h3 className="font-bold mb-2">Technische Info</h3>
        <p className="text-sm text-gray-500">
          Datenbank-Engine: SQLite via WebAssembly (sql.js 1.10.3)<br/>
          Speicherort (Cache): Browser LocalStorage (mfm_sqlite_db)<br/>
          Tabellen: vehicles, logs, orders
        </p>
      </div>
    </div>
  );
};

const DashboardView = ({ logs, vehicles, onComplete, onEdit, onDelete, onAdd }: any) => {
  const [filterType, setFilterType] = useState('');
  const [filterVehicle, setFilterVehicle] = useState('');
  const [showDone, setShowDone] = useState(false);

  // Create virtual entries for dashboard from due dates
  const dueInspections = useMemo(() => {
    const alerts: any[] = [];
    vehicles.forEach((v: Vehicle) => {
      const check = (date: string | undefined, type: string) => {
        if (!date) return;
        const [m, y] = date.split('/').map(Number);
        const due = new Date(y, m - 1); // 1st of that month
        const now = new Date();
        // Show if due within next 30 days or overdue
        if (due.getTime() < now.getTime() + 30 * 24 * 60 * 60 * 1000) {
          alerts.push({
            id: `sys_${v.id}_${type}`,
            vehicleId: v.id,
            type: EntryType.PRUEFUNG,
            inspectionType: type,
            description: `Fällige ${type}: ${date}`,
            dateAdded: getTodayDate(),
            status: 'OPEN',
            isSystem: true,
            rawDate: date
          });
        }
      };
      check(v.nextHU, 'HU');
      check(v.nextSP, 'SP');
      check(v.nextUVV, 'UVV');
      check(v.nextTacho, 'Tacho');
    });
    return alerts;
  }, [vehicles]);

  const filteredLogs = [...logs, ...dueInspections].filter((l: any) => {
    if (!showDone && l.status === 'DONE') return false;
    if (showDone && l.status !== 'DONE') return false;
    if (filterType && l.type !== filterType) return false;
    if (filterVehicle && l.vehicleId !== filterVehicle) return false;
    return true;
  }).sort((a, b) => {
    // Sort by license plate
    const vA = vehicles.find((v: any) => v.id === a.vehicleId)?.licensePlate || '';
    const vB = vehicles.find((v: any) => v.id === b.vehicleId)?.licensePlate || '';
    return vA.localeCompare(vB);
  });

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded shadow no-print">
        <h2 className="text-2xl font-bold text-gray-800">Dashboard / ToDo</h2>
        <div className="flex flex-wrap gap-2 items-center">
          <select className="border p-2 rounded" value={filterVehicle} onChange={e => setFilterVehicle(e.target.value)}>
            <option value="">Alle Fahrzeuge</option>
            {vehicles.map((v: any) => <option key={v.id} value={v.id}>{v.licensePlate}</option>)}
          </select>
          <select className="border p-2 rounded" value={filterType} onChange={e => setFilterType(e.target.value)}>
            <option value="">Alle Typen</option>
            {Object.values(EntryType).map(t => <option key={t} value={t}>{t}</option>)}
          </select>
          <label className="flex items-center gap-2 text-sm">
            <input type="checkbox" checked={showDone} onChange={e => setShowDone(e.target.checked)} />
            Erledigte anzeigen
          </label>
          <button onClick={onAdd} className="bg-primary hover:bg-blue-700 text-white px-4 py-2 rounded flex items-center gap-2">
            <Icons.Plus /> Eintrag
          </button>
        </div>
      </div>

      <div className="bg-white rounded shadow overflow-hidden">
        <table className="w-full text-left border-collapse">
          <thead className="bg-gray-100 text-gray-600 uppercase text-sm">
            <tr>
              <th className="p-3">Kennzeichen</th>
              <th className="p-3">Typ</th>
              <th className="p-3">Beschreibung</th>
              <th className="p-3">Datum</th>
              <th className="p-3 text-right">Aktion</th>
