    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded shadow-lg w-full max-w-lg p-6">
        <h2 className="text-xl font-bold mb-4">{entry ? 'Eintrag bearbeiten' : 'Neuer Eintrag'}</h2>

        <div className="space-y-4">
          <div>
            <label className="block text-sm font-bold mb-1">Fahrzeug</label>
            <select className="w-full border p-2 rounded" value={form.vehicleId} onChange={e => setForm({...form, vehicleId: e.target.value})}>
               {vehicles.map((v:any) => <option key={v.id} value={v.id}>{v.licensePlate}</option>)}
            </select>
          </div>

          <div>
            <label className="block text-sm font-bold mb-1">Art</label>
            <select className="w-full border p-2 rounded" value={form.type} onChange={e => setForm({...form, type: e.target.value as EntryType})}>
              {Object.values(EntryType).map(t => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>

          {form.type === EntryType.PRUEFUNG && (
             <div>
              <label className="block text-sm font-bold mb-1">Prüfungsart</label>
              <select className="w-full border p-2 rounded" value={form.inspectionType || 'HU'} onChange={e => setForm({...form, inspectionType: e.target.value as any})}>
                <option value="HU">Hauptuntersuchung (HU)</option>
                <option value="SP">Sicherheitsprüfung (SP)</option>
                <option value="Tacho">Tachoprüfung</option>
                <option value="UVV">UVV</option>
              </select>
            </div>
          )}

          <div>
             <label className="block text-sm font-bold mb-1">Beschreibung</label>
             <textarea className="w-full border p-2 rounded" rows={3} value={form.description} onChange={e => setForm({...form, description: e.target.value})} />
          </div>

          <div>
             <label className="block text-sm font-bold mb-1">KM-Stand / Betriebsstunden (bei Erledigung)</label>
             <input type="number" className="w-full border p-2 rounded" value={form.mileage || ''} onChange={e => setForm({...form, mileage: parseInt(e.target.value)})} />
          </div>
        </div>

        <div className="flex justify-end gap-2 mt-6">
          <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">Abbrechen</button>
          <button onClick={() => handleSave(true)} className="px-4 py-2 bg-blue-100 text-blue-800 rounded hover:bg-blue-200">Speichern & Weiter</button>
          <button onClick={() => handleSave(false)} className="px-4 py-2 bg-primary text-white rounded hover:bg-blue-700">Speichern</button>
        </div>
      </div>
    </div>
  );
};

const OrderModal = ({ isOpen, onClose, order, vehicles, onSave }: any) => {
  const [form, setForm] = useState<Partial<Order>>({ 
    description: '', 
    vehicleId: '',
    ...order 
  });

  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded shadow-lg w-full max-w-md p-6">
        <h2 className="text-xl font-bold mb-4">{order ? 'Bestellung bearbeiten' : 'Ersatzteil bestellen'}</h2>
        <div className="space-y-4">
           <div>
             <label className="block text-sm font-bold mb-1">Bezeichnung / Teil</label>
             <input className="w-full border p-2 rounded" value={form.description} onChange={e => setForm({...form, description: e.target.value})} />
          </div>
          <div>
            <label className="block text-sm font-bold mb-1">Für Fahrzeug (Optional)</label>
            <select className="w-full border p-2 rounded" value={form.vehicleId || ''} onChange={e => setForm({...form, vehicleId: e.target.value})}>
               <option value="">-- Allgemein / Lager --</option>
               {vehicles.map((v:any) => <option key={v.id} value={v.id}>{v.licensePlate}</option>)}
            </select>
          </div>
        </div>
        <div className="flex justify-end gap-2 mt-6">
          <button onClick={onClose} className="px-4 py-2 text-gray-600">Abbrechen</button>
          <button onClick={() => onSave(form)} className="px-4 py-2 bg-primary text-white rounded">Speichern</button>
        </div>
      </div>
    </div>
  );
}

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

