  Printer: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect width="12" height="8" x="6" y="14"/></svg>,
  Filter: () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/></svg>,
  Database: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M21 12c0 1.66-4 3-9 3s-9-1.34-9-3"/><path d="M3 5v14c0 1.66 4 3 9 3s 9-1.34 9-3V5"/></svg>,
  Download: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" x2="12" y1="15" y2="3"/></svg>,
  Upload: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" x2="12" y1="3" y2="15"/></svg>,
  Alert: () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" x2="12" y1="8" y2="12"/><line x1="12" x2="12.01" y1="16" y2="16"/></svg>,
};

// --- HELPER FUNCTIONS ---

const generateId = () => Math.random().toString(36).substr(2, 9);
const getTodayDate = () => new Date().toISOString().split('T')[0];

const isValidDateMMYYYY = (val: string) => /^\d{2}\/\d{4}$/.test(val);

// --- MAIN APPLICATION ---

const App = () => {
  const [activeTab, setActiveTab] = useState('todo');

  // Database State
  const [db, setDb] = useState<any>(null);
  const [isDbReady, setIsDbReady] = useState(false);

  // App Data State (synced with DB)
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);

  // Admin Mode
  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');

  // Modals
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [editingVehicle, setEditingVehicle] = useState<Vehicle | null>(null);

  const [showEntryModal, setShowEntryModal] = useState(false);
  const [editingEntry, setEditingEntry] = useState<LogEntry | null>(null);

  const [showOrderModal, setShowOrderModal] = useState(false);
  const [editingOrder, setEditingOrder] = useState<Order | null>(null);

  const [showInspectionCompleteModal, setShowInspectionCompleteModal] = useState(false);
  const [completingInspection, setCompletingInspection] = useState<{entry: LogEntry, newDate: string} | null>(null);

  // --- SQLITE INIT ---
  useEffect(() => {
    const initDB = async () => {
      try {
        const SQL = await initSqlJs({
          // Force use of same version WASM file to prevent LinkError with JS glue code
          locateFile: (file: string) => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/${file}`
        });

        // Check if we have saved binary data in LocalStorage (Persistence layer)
        const savedDb = localStorage.getItem('mfm_sqlite_db');
        let database;

        if (savedDb) {
          const binaryArray = new Uint8Array(savedDb.split(',').map(Number));
          database = new SQL.Database(binaryArray);
        } else {
          database = new SQL.Database();
          // Create Tables
          database.run(`
            CREATE TABLE IF NOT EXISTS vehicles (
              id TEXT PRIMARY KEY, 
              licensePlate TEXT, 
              type TEXT, 
              manufacturer TEXT, 
              model TEXT, 
              vin TEXT, 
              year INTEGER, 
              notes TEXT, 
              coupledVehicleId TEXT, 
              nextHU TEXT, 
              nextSP TEXT, 
              nextUVV TEXT, 
              nextTacho TEXT, 
              currentMileage INTEGER
            );
            CREATE TABLE IF NOT EXISTS logs (
              id TEXT PRIMARY KEY, 
              vehicleId TEXT, 
              type TEXT, 
              description TEXT, 
              priority TEXT,
              dateAdded TEXT, 
              dateCompleted TEXT, 
              status TEXT, 
              mileage INTEGER, 
              inspectionType TEXT
            );
            CREATE TABLE IF NOT EXISTS orders (
              id TEXT PRIMARY KEY, 
              description TEXT, 
              vehicleId TEXT, 
              dateAdded TEXT, 
              status TEXT
            );
          `);

          // MIGRATE OLD DATA (from legacy LocalStorage keys if they exist)
          const oldVehicles = localStorage.getItem('mfm_vehicles');
          const oldLogs = localStorage.getItem('mfm_logs');
          const oldOrders = localStorage.getItem('mfm_orders');

          if (oldVehicles) {
            JSON.parse(oldVehicles).forEach((v: Vehicle) => {
              database.run(`INSERT OR IGNORE INTO vehicles VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`, 
                [v.id, v.licensePlate, v.type, v.manufacturer, v.model, v.vin, v.year, v.notes, v.coupledVehicleId, v.nextHU, v.nextSP, v.nextUVV, v.nextTacho, v.currentMileage]);
            });
          }
          if (oldLogs) {
            JSON.parse(oldLogs).forEach((l: LogEntry) => {
               database.run(`INSERT OR IGNORE INTO logs VALUES (?,?,?,?,?,?,?,?,?,?)`, 
                [l.id, l.vehicleId, l.type, l.description, l.priority || Priority.NORMAL, l.dateAdded, l.dateCompleted, l.status, l.mileage, l.inspectionType]);
            });
          }
          if (oldOrders) {
            JSON.parse(oldOrders).forEach((o: Order) => {
              database.run(`INSERT OR IGNORE INTO orders VALUES (?,?,?,?,?)`, 
                [o.id, o.description, o.vehicleId, o.dateAdded, o.status]);
            });
          }
        }

        // --- MIGRATIONS FOR EXISTING DBS ---
        // Check if priority column exists in logs
        try {
          database.exec("SELECT priority FROM logs LIMIT 1");
        } catch (e) {
          // Column missing, add it
          console.log("Migrating: Adding priority column to logs");
          database.run("ALTER TABLE logs ADD COLUMN priority TEXT");
          database.run("UPDATE logs SET priority = ?", [Priority.NORMAL]);
        }

        setDb(database);
        setIsDbReady(true);
      } catch (e) {
        console.error("Failed to init database", e);
        alert("Fehler beim Laden der Datenbank! Details in der Konsole.");
      }
    };

    initDB();
  }, []);

  // --- DATA LOADING ---
  const refreshData = useCallback(() => {
    if (!db) return;

    // Load Vehicles
    const vRes = db.exec("SELECT * FROM vehicles");
    if (vRes.length > 0) {
      const cols = vRes[0].columns;
      const rows = vRes[0].values;
      const loadedVehicles = rows.map((row: any[]) => {
        const obj: any = {};
        cols.forEach((col: string, i: number) => obj[col] = row[i]);
        return obj as Vehicle;
      });
      setVehicles(loadedVehicles);
    } else {
      setVehicles([]);
    }

    // Load Logs
    const lRes = db.exec("SELECT * FROM logs");
    if (lRes.length > 0) {
      const cols = lRes[0].columns;
      const rows = lRes[0].values;
      const loadedLogs = rows.map((row: any[]) => {
        const obj: any = {};
        cols.forEach((col: string, i: number) => obj[col] = row[i]);
        if(!obj.priority) obj.priority = Priority.NORMAL; // Fallback
        return obj as LogEntry;
      });
      setLogs(loadedLogs);
    } else {
      setLogs([]);
    }

    // Load Orders
    const oRes = db.exec("SELECT * FROM orders");
    if (oRes.length > 0) {
      const cols = oRes[0].columns;
      const rows = oRes[0].values;
      const loadedOrders = rows.map((row: any[]) => {
        const obj: any = {};
        cols.forEach((col: string, i: number) => obj[col] = row[i]);
        return obj as Order;
      });
      setOrders(loadedOrders);
    } else {
      setOrders([]);
    }

  }, [db]);

  useEffect(() => {
    if (isDbReady) {
      refreshData();
    }
  }, [isDbReady, refreshData]);

  // --- PERSISTENCE HELPER ---
  const saveDbToStorage = () => {
    if (!db) return;
    const binaryArray = db.export();
    // Save as comma separated string to localstorage for auto-resume
    // Note: For large DBs, IndexedDB would be better, but sticking to simple setup for now.
    const str = binaryArray.toString();
    localStorage.setItem('mfm_sqlite_db', str);
  };

  const handleAdminLogin = () => {
    if (adminPassword === 'Co33ing#admin') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setAdminPassword('');
    } else {
      alert('Falsches Passwort!');
    }
  };

  // --- LOGIC: VEHICLE COUPLING ---
  const handleSaveVehicle = (v: Vehicle) => {
    // Check coupling logic
    if (v.type === VehicleType.LKW && v.coupledVehicleId) {
      const existingCoupling = vehicles.find(
        other => other.id !== v.id && other.type === VehicleType.LKW && other.coupledVehicleId === v.coupledVehicleId
      );
      if (existingCoupling) {
        const confirm = window.confirm(`Der Auflieger ist bereits mit ${existingCoupling.licensePlate} gekoppelt. Verbindung lösen und neu zuordnen?`);
        if (!confirm) return;
        // Remove old coupling in DB
        db.run("UPDATE vehicles SET coupledVehicleId = NULL WHERE id = ?", [existingCoupling.id]);
      }
    }

    const isEdit = editingVehicle !== null;
    const id = v.id || generateId();

    db.run(`INSERT OR REPLACE INTO vehicles VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`, [
      id, 
      v.licensePlate, 
      v.type, 
      v.manufacturer, 
      v.model, 
      v.vin, 
      v.year, 
      v.notes, 
      v.coupledVehicleId || null, 
      v.nextHU || null, 
      v.nextSP || null, 
      v.nextUVV || null, 
      v.nextTacho || null, 
      v.currentMileage || null
    ]);

    saveDbToStorage();
    refreshData();
    setShowVehicleModal(false);
    setEditingVehicle(null);
  };

  const deleteVehicle = (id: string) => {
    if (confirm('Fahrzeug wirklich löschen? Alle Historien bleiben erhalten.')) {
      db.run("DELETE FROM vehicles WHERE id = ?", [id]);
      saveDbToStorage();
      refreshData();
    }
  };

  // --- LOGIC: ENTRIES ---
  const handleSaveEntries = (entries: Partial<LogEntry>[]) => {

    entries.forEach(entry => {
        const id = entry.id || generateId();
        const dateAdded = entry.dateAdded || getTodayDate();
        const status = entry.status || 'OPEN';
        const priority = entry.priority || Priority.NORMAL;

        db.run(`INSERT OR REPLACE INTO logs VALUES (?,?,?,?,?,?,?,?,?,?)`, [
            id,
            entry.vehicleId,
            entry.type,
            entry.description,
            priority,
            dateAdded,
            entry.dateCompleted || null,
            status,
            entry.mileage || null,
            entry.inspectionType || null
        ]);
    });

    saveDbToStorage();
    refreshData();
    setShowEntryModal(false);
    setEditingEntry(null);
  };

  const handleCompleteEntry = (entry: LogEntry) => {
    if (entry.type === EntryType.PRUEFUNG && entry.inspectionType) {
      setCompletingInspection({ entry, newDate: '' });
      setShowInspectionCompleteModal(true);
    } else {
      db.run("UPDATE logs SET status = ?, dateCompleted = ? WHERE id = ?", ['DONE', getTodayDate(), entry.id]);
      saveDbToStorage();
      refreshData();
    }
  };

  const confirmInspectionCompletion = () => {
    if (!completingInspection || !isValidDateMMYYYY(completingInspection.newDate)) {
      alert('Bitte gültiges Datum im Format MM/YYYY eingeben.');
      return;
    }

    const { entry, newDate } = completingInspection;

    // Update Vehicle Dates
    let dateField = '';
    if (entry.inspectionType === 'HU') dateField = 'nextHU';
    if (entry.inspectionType === 'SP') dateField = 'nextSP';
    if (entry.inspectionType === 'UVV') dateField = 'nextUVV';
    if (entry.inspectionType === 'Tacho') dateField = 'nextTacho';

    if (dateField) {
      db.run(`UPDATE vehicles SET ${dateField} = ? WHERE id = ?`, [newDate, entry.vehicleId]);
    }

    // Update Log
    db.run("UPDATE logs SET status = ?, dateCompleted = ? WHERE id = ?", ['DONE', getTodayDate(), entry.id]);

    saveDbToStorage();
    refreshData();
    setShowInspectionCompleteModal(false);
    setCompletingInspection(null);
  };

  const deleteLog = (id: string, skipConfirm = false) => {
    if (skipConfirm || confirm('Eintrag löschen?')) {
      db.run("DELETE FROM logs WHERE id = ?", [id]);
      saveDbToStorage();
      refreshData();
    }
  };

  // --- LOGIC: ORDERS ---
  const handleSaveOrder = (formData: Partial<Order>) => {
    const id = editingOrder?.id || generateId();
    const dateAdded = editingOrder?.dateAdded || getTodayDate();
    // Fix: Use the new status from formData if available, otherwise default to OFFEN (or existing)
    const status = formData.status || editingOrder?.status || OrderStatus.OFFEN;

    db.run(`INSERT OR REPLACE INTO orders VALUES (?,?,?,?,?)`, [
      id,
      formData.description,
      formData.vehicleId || null,
      dateAdded,
      status
    ]);

    saveDbToStorage();
    refreshData();
    setShowOrderModal(false);
    setEditingOrder(null);
  };

  const updateOrderStatus = (id: string, status: OrderStatus) => {
    db.run("UPDATE orders SET status = ? WHERE id = ?", [status, id]);
    saveDbToStorage();
    refreshData();
  };

  const deleteOrder = (id: string, skipConfirm: boolean = false) => {
    if(!skipConfirm && !confirm('Bestellung wirklich löschen?')) {
        return;
    }
    db.run("DELETE FROM orders WHERE id = ?", [id]);
    saveDbToStorage();
    refreshData();
  }

  // --- RENDER HELPERS ---
  const getVehicleLabel = (vid: string) => {
    const v = vehicles.find(x => x.id === vid);
    if (!v) return 'Unbekannt';
    let label = v.licensePlate;
    // Show coupling
    if (v.type === VehicleType.LKW && v.coupledVehicleId) {
      const coupled = vehicles.find(c => c.id === v.coupledVehicleId);
      if (coupled) label += ` [${coupled.licensePlate}]`;
    }
    return label;
  };

  if (!isDbReady) {
    return <div className="flex h-screen items-center justify-center">Datenbank wird geladen...</div>;
  }

  return (
    <div className="flex h-screen flex-col md:flex-row font-sans">
      {/* SIDEBAR NAVIGATION */}
      <div className="w-full md:w-64 bg-slate-800 text-white flex-shrink-0 flex flex-col no-print">
        <div className="p-4 font-bold text-xl border-b border-slate-700">Fuhrpark Manager</div>
        <nav className="flex-1 p-2 space-y-1">
          {[
            { id: 'todo', label: 'ToDo', icon: Icons.Dashboard },
            { id: 'termine', label: 'Prüftermine', icon: Icons.Calendar },
            { id: 'bestellungen', label: 'Bestellliste', icon: Icons.ShoppingCart },
            { id: 'fahrzeuge', label: 'Fahrzeugstamm', icon: Icons.Truck },
            { id: 'historie', label: 'Historie & Suche', icon: Icons.History },
          ].map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded text-left transition-colors ${activeTab === item.id ? 'bg-primary text-white' : 'text-slate-300 hover:bg-slate-700'}`}
            >
              <item.icon />
              {item.label}
            </button>
          ))}

          <div className="pt-4 mt-4 border-t border-slate-700">
            <button
                onClick={() => setActiveTab('settings')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded text-left transition-colors ${activeTab === 'settings' ? 'bg-orange-600 text-white' : 'text-slate-300 hover:bg-slate-700'}`}
              >
              <Icons.Database />
              Datenbank / System
            </button>
          </div>
        </nav>
        <div className="p-4 border-t border-slate-700 text-xs text-slate-500 flex justify-between items-center">
          <span>v1.5 (SQLite)</span>
          <button onClick={() => setShowAdminLogin(true)} className="opacity-50 hover:opacity-100">
            <Icons.Lock />
          </button>
        </div>
      </div>

      {/* MAIN CONTENT AREA */}
      <main className="flex-1 overflow-auto bg-gray-50 p-4 md:p-8 relative">

        {/* --- DASHBOARD --- */}
        {activeTab === 'todo' && (
          <DashboardView 
            logs={logs} 
            vehicles={vehicles} 
            onComplete={handleCompleteEntry}
            onEdit={(l) => { setEditingEntry(l); setShowEntryModal(true); }}
            onDelete={deleteLog}
            onAdd={() => { setEditingEntry(null); setShowEntryModal(true); }}
          />
        )}

        {/* --- FAHRZEUGE --- */}
        {activeTab === 'fahrzeuge' && (
          <VehicleListView 
            vehicles={vehicles} 
            onEdit={(v) => { setEditingVehicle(v); setShowVehicleModal(true); }}
            onDelete={deleteVehicle}
            onAdd={() => { setEditingVehicle(null); setShowVehicleModal(true); }}
          />
        )}

        {/* --- TERMINE --- */}
        {activeTab === 'termine' && (
          <AppointmentsView vehicles={vehicles} />
        )}

        {/* --- BESTELLUNGEN --- */}
        {activeTab === 'bestellungen' && (
          <OrdersView 
            orders={orders} 
            vehicles={vehicles}
            onAdd={() => { setEditingOrder(null); setShowOrderModal(true); }}
            onEdit={(o) => { setEditingOrder(o); setShowOrderModal(true); }}
            onStatusChange={updateOrderStatus}
            onDelete={deleteOrder}
          />
        )}

        {/* --- HISTORIE --- */}
        {activeTab === 'historie' && (
          <HistoryView 
            logs={logs} 
            vehicles={vehicles} 
            isAdmin={isAdmin}
            onEdit={(l) => { setEditingEntry(l); setShowEntryModal(true); }}
            onDelete={deleteLog}
          />
        )}

        {/* --- SETTINGS / DB --- */}
        {activeTab === 'settings' && (
          <DatabaseView db={db} setDb={setDb} refreshData={refreshData} />
        )}

      </main>

      {/* --- MODALS --- */}

      {/* Vehicle Modal */}
      {showVehicleModal && (
        <VehicleModal 
          isOpen={showVehicleModal} 
          onClose={() => setShowVehicleModal(false)}
          vehicle={editingVehicle}
          allVehicles={vehicles}
          onSave={handleSaveVehicle}
        />
      )}

      {/* Entry Modal */}
      {showEntryModal && (
        <EntryModal 
          isOpen={showEntryModal}
          onClose={() => setShowEntryModal(false)}
          entry={editingEntry}
          vehicles={vehicles}
          onSave={handleSaveEntries}
          onDelete={deleteLog}
        />
      )}

      {/* Order Modal */}
      {showOrderModal && (
        <OrderModal
          isOpen={showOrderModal}
          onClose={() => setShowOrderModal(false)}
          order={editingOrder}
          vehicles={vehicles}
          onSave={handleSaveOrder}
          onDelete={deleteOrder}
        />
      )}

      {/* Admin Login Modal */}
      {showAdminLogin && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded shadow-lg w-80">
            <h3 className="text-lg font-bold mb-4">Admin Login</h3>
            <input 
              type="password" 
              className="w-full border p-2 rounded mb-4" 
              placeholder="Passwort"
              value={adminPassword}
              onChange={e => setAdminPassword(e.target.value)}
            />
            <div className="flex justify-end gap-2">
              <button onClick={() => setShowAdminLogin(false)} className="px-4 py-2 text-gray-600">Abbrechen</button>
              <button onClick={handleAdminLogin} className="px-4 py-2 bg-primary text-white rounded">Login</button>
            </div>
          </div>
        </div>
      )}

      {/* Inspection Complete Modal */}
      {showInspectionCompleteModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded shadow-lg w-96">
            <h3 className="text-lg font-bold mb-4">Prüfung abgeschlossen</h3>
            <p className="mb-2 text-sm text-gray-600">Bitte neuen Termin für {completingInspection?.entry.inspectionType} eingeben:</p>
            <input 
              type="text" 
              className="w-full border p-2 rounded mb-4" 
              placeholder="MM/YYYY"
              value={completingInspection?.newDate || ''}
              onChange={e => setCompletingInspection(prev => prev ? {...prev, newDate: e.target.value} : null)}
            />
            <div className="flex justify-end gap-2">
              <button onClick={() => setShowInspectionCompleteModal(false)} className="px-4 py-2 text-gray-600">Abbrechen</button>
              <button onClick={confirmInspectionCompletion} className="px-4 py-2 bg-green-600 text-white rounded">Bestätigen & Speichern</button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

// --- SUB-VIEWS ---

const DatabaseView = ({ db, setDb, refreshData }: any) => {
  const [msg, setMsg] = useState('');

  const exportDB = () => {
    const binaryArray = db.export();
    const blob = new Blob([binaryArray], {type: "application/x-sqlite3"});
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `fuhrpark_${getTodayDate()}.sqlite`;
    a.click();
    window.URL.revokeObjectURL(url);
    setMsg('Datenbank wurde heruntergeladen.');
  };

  const importDB = async (e: any) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const uInt8Array = new Uint8Array(reader.result as ArrayBuffer);
        const SQL = await initSqlJs({ locateFile: file => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/${file}` });
        const newDb = new SQL.Database(uInt8Array);
        setDb(newDb);
        // Persist immediately
        const str = uInt8Array.toString();
        localStorage.setItem('mfm_sqlite_db', str);

        // Trigger refresh
        setTimeout(() => {
          window.location.reload(); // Hard reload to ensure clean state
        }, 500);

      } catch (err) {
        console.error(err);
        alert('Fehler beim Laden der Datei. Ist es eine gültige SQLite Datei?');
      }
    };
    reader.readAsArrayBuffer(file);
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded shadow border-l-4 border-orange-500">
        <h2 className="text-2xl font-bold text-gray-800 mb-2">NAS & Mehrbenutzer Synchronisation</h2>
        <p className="text-gray-600 mb-4">
          Da diese App zentral auf einem NAS im Browser läuft, können Daten nicht automatisch auf die Festplatte des Servers geschrieben werden. 
          Um Daten zwischen verschiedenen Nutzern oder Geräten zu teilen, nutzen Sie bitte die Export- und Import-Funktion.
        </p>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-6">
          <div className="border p-4 rounded bg-gray-50">
            <h3 className="font-bold flex items-center gap-2 mb-2"><Icons.Download /> Speichern (Export)</h3>
            <p className="text-sm text-gray-600 mb-3">
              Speichern Sie den aktuellen Stand als <code>.sqlite</code> Datei auf Ihrem NAS-Laufwerk ab, wenn Sie Ihre Arbeit beendet haben.
            </p>
