const DashboardView = ({ logs, vehicles, onComplete, onEdit, onDelete, onAdd }: any) => {
  const [filterType, setFilterType] = useState('');
  const [filterVehicle, setFilterVehicle] = useState('');
  const [filterPriority, setFilterPriority] = useState('');
  const [showDone, setShowDone] = useState(false);

  // Create virtual entries for dashboard from due dates
  const dueInspections = useMemo(() => {
    const alerts: any[] = [];
    vehicles.forEach((v: Vehicle) => {
      const check = (date: string | undefined, type: string) => {
        if (!date) return;
        const [m, y] = date.split('/').map(Number);
        const due = new Date(y, m - 1); // 1st of that month
        const now = new Date();
        // Show if due within next 30 days or overdue
        if (due.getTime() < now.getTime() + 30 * 24 * 60 * 60 * 1000) {
          alerts.push({
            id: `sys_${v.id}_${type}`,
            vehicleId: v.id,
            type: EntryType.PRUEFUNG,
            inspectionType: type,
            description: `Fällige ${type}: ${date}`,
            priority: Priority.HIGH,
            dateAdded: getTodayDate(),
            status: 'OPEN',
            isSystem: true,
            rawDate: date
          });
        }
      };
      check(v.nextHU, 'HU');
      check(v.nextSP, 'SP');
      check(v.nextUVV, 'UVV');
      check(v.nextTacho, 'Tacho');
    });
    return alerts;
  }, [vehicles]);

  const filteredLogs = [...logs, ...dueInspections].filter((l: any) => {
    if (!showDone && l.status === 'DONE') return false;
    if (showDone && l.status !== 'DONE') return false;
    if (filterType && l.type !== filterType) return false;
    if (filterVehicle && l.vehicleId !== filterVehicle) return false;
    if (filterPriority && l.priority !== filterPriority) return false;
    return true;
  }).sort((a, b) => {
    // Sort logic: HIGH Priority first, then System alerts, then Date
    const priorityScore = (p: Priority) => p === Priority.HIGH ? 3 : p === Priority.NORMAL ? 2 : 1;
    const scoreA = priorityScore(a.priority || Priority.NORMAL);
    const scoreB = priorityScore(b.priority || Priority.NORMAL);

    if (scoreA !== scoreB) return scoreB - scoreA;
    if (a.isSystem !== b.isSystem) return a.isSystem ? -1 : 1;

    return a.vehicleId.localeCompare(b.vehicleId);
  });

  const getPriorityColor = (p: Priority) => {
    switch (p) {
      case Priority.HIGH: return 'bg-red-100 text-red-800 border-red-200';
      case Priority.LOW: return 'bg-gray-100 text-gray-800 border-gray-200';
      default: return 'bg-blue-50 text-blue-800 border-blue-200';
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded shadow no-print">
        <h2 className="text-2xl font-bold text-gray-800">ToDo Liste</h2>
        <div className="flex flex-wrap gap-2 items-center">
          <select className="border p-2 rounded text-sm" value={filterVehicle} onChange={e => setFilterVehicle(e.target.value)}>
            <option value="">Alle Fahrzeuge</option>
            {vehicles.map((v: any) => <option key={v.id} value={v.id}>{v.licensePlate}</option>)}
          </select>
          <select className="border p-2 rounded text-sm" value={filterType} onChange={e => setFilterType(e.target.value)}>
            <option value="">Alle Typen</option>
            {Object.values(EntryType).map(t => <option key={t} value={t}>{t}</option>)}
          </select>
          <select className="border p-2 rounded text-sm" value={filterPriority} onChange={e => setFilterPriority(e.target.value)}>
            <option value="">Alle Prioritäten</option>
            {Object.values(Priority).map(p => <option key={p} value={p}>{p}</option>)}
          </select>
          <label className="flex items-center gap-2 text-sm bg-gray-50 px-2 py-2 rounded border">
            <input type="checkbox" checked={showDone} onChange={e => setShowDone(e.target.checked)} />
            Erledigte
          </label>
          <button onClick={onAdd} className="bg-primary hover:bg-blue-700 text-white px-4 py-2 rounded flex items-center gap-2 shadow-sm">
            <Icons.Plus /> Eintrag
          </button>
        </div>
      </div>

      <div className="bg-white rounded shadow overflow-hidden">
        <table className="w-full text-left border-collapse">
          <thead className="bg-gray-100 text-gray-600 uppercase text-sm">
            <tr>
              <th className="p-3">Kennzeichen</th>
              <th className="p-3">Prio</th>
              <th className="p-3">Typ</th>
              <th className="p-3">Beschreibung</th>
              <th className="p-3">Datum</th>
              <th className="p-3 text-right">Status</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {filteredLogs.length === 0 && (
              <tr><td colSpan={6} className="p-8 text-center text-gray-400">Keine Einträge vorhanden.</td></tr>
            )}
            {filteredLogs.map((l: any) => {
              const vehicle = vehicles.find((v: any) => v.id === l.vehicleId);
              const label = vehicle ? (
                  <span>
                    {vehicle.licensePlate} 
                    {vehicle.type === VehicleType.LKW && vehicle.coupledVehicleId && (
                      <span className="text-xs text-gray-500 ml-1">
                         [{vehicles.find((x:any) => x.id === vehicle.coupledVehicleId)?.licensePlate}]
                      </span>
                    )}
                  </span>
                ) : '???';

              return (
                <tr 
                  key={l.id} 
                  className={`hover:bg-gray-50 cursor-pointer transition-colors ${l.isSystem ? 'bg-red-50' : ''}`}
                  onClick={() => !l.isSystem && onEdit(l)}
                >
                  <td className="p-3 font-medium">{label}</td>
                  <td className="p-3">
                    <span className={`px-2 py-1 rounded text-xs border ${getPriorityColor(l.priority)}`}>
                      {l.priority || Priority.NORMAL}
                    </span>
                  </td>
                  <td className="p-3">
                    <span className={`px-2 py-1 rounded text-xs text-white ${l.type === EntryType.REPARATUR ? 'bg-red-500' : l.type === EntryType.WARTUNG ? 'bg-orange-500' : 'bg-blue-500'}`}>
                      {l.type}
                    </span>
                    {l.isSystem && <span className="ml-2 text-red-600 text-xs font-bold">AUTO</span>}
                  </td>
                  <td className="p-3">{l.description}</td>
                  <td className="p-3 text-sm text-gray-500">{l.dateAdded}</td>
                  <td className="p-3 text-right" onClick={(e) => e.stopPropagation()}>
                    {l.status === 'OPEN' && (
                      <button 
                        onClick={() => onComplete(l)} 
                        title="Erledigt markieren"
                        className="p-1 text-green-600 hover:bg-green-100 rounded border border-transparent hover:border-green-200"
                      >
                        <Icons.Check />
                      </button>
                    )}
                    {l.status === 'DONE' && <span className="text-green-600 font-bold text-xs">ERLEDIGT</span>}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

