    if (!date) return 'text-gray-400';
    const [m, y] = date.split('/').map(Number);
    const due = new Date(y, m - 1);
    const now = new Date();
    if (due < now) return 'text-red-600 font-bold bg-red-100 px-1 rounded'; // Overdue
    if (due.getTime() < now.getTime() + 60 * 24 * 60 * 60 * 1000) return 'text-orange-600 font-bold'; // Due soon
    return 'text-green-600';
