        <h2 className="text-xl font-bold mb-4">{vehicle ? 'Fahrzeug bearbeiten' : 'Neues Fahrzeug'}</h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
          <div>
            <label className="block text-sm font-bold mb-1">Typ</label>
            <select className="w-full border p-2 rounded" value={form.type} onChange={e => setForm({...form, type: e.target.value as VehicleType})}>
