                      <option key={v.id} value={v.id}>{v.licensePlate} {v.coupledVehicleId ? '(Bereits gekoppelt!)' : ''}</option>
                 ))}
               </select>
            </div>
          )}

          {/* DATES */}
          <div className="col-span-2 grid grid-cols-2 md:grid-cols-4 gap-2 border-t pt-4">
            <div>
               <label className="block text-xs font-bold mb-1">Nächste HU (MM/YYYY)</label>
               <input className="w-full border p-2 rounded text-sm" placeholder="MM/YYYY" value={form.nextHU || ''} onChange={e => setForm({...form, nextHU: e.target.value})} />
            </div>
            {(form.type === VehicleType.LKW || form.type === VehicleType.AUFLIEGER) && (
              <div>
                 <label className="block text-xs font-bold mb-1">Nächste SP</label>
                 <input className="w-full border p-2 rounded text-sm" placeholder="MM/YYYY" value={form.nextSP || ''} onChange={e => setForm({...form, nextSP: e.target.value})} />
              </div>
            )}
             {form.type === VehicleType.LKW && (
              <div>
                 <label className="block text-xs font-bold mb-1">Nächste Tacho</label>
                 <input className="w-full border p-2 rounded text-sm" placeholder="MM/YYYY" value={form.nextTacho || ''} onChange={e => setForm({...form, nextTacho: e.target.value})} />
              </div>
            )}
             {form.type === VehicleType.MASCHINE && (
              <div>
                 <label className="block text-xs font-bold mb-1">Nächste UVV</label>
                 <input className="w-full border p-2 rounded text-sm" placeholder="MM/YYYY" value={form.nextUVV || ''} onChange={e => setForm({...form, nextUVV: e.target.value})} />
              </div>
            )}
          </div>

          <div className="col-span-2">
             <label className="block text-sm font-bold mb-1">Bemerkungen</label>
             <textarea className="w-full border p-2 rounded" rows={3} value={form.notes} onChange={e => setForm({...form, notes: e.target.value})} />
          </div>
        </div>

        <div className="flex justify-end gap-2">
          <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">Abbrechen</button>
          <button onClick={() => onSave(form)} className="px-4 py-2 bg-primary text-white rounded hover:bg-blue-700">Speichern</button>
        </div>
      </div>
    </div>
