const EntryModal = ({ isOpen, onClose, entry, vehicles, onSave, onDelete }: any) => {
  // If entry exists, we are editing SINGLE item. 
  // If entry is null, we are creating BATCH items.
  const isEditMode = !!entry;

  const [commonDate, setCommonDate] = useState(entry?.dateAdded || getTodayDate());
  const [commonVehicle, setCommonVehicle] = useState(entry?.vehicleId || vehicles[0]?.id || '');
  const [commonType, setCommonType] = useState<EntryType>(entry?.type || EntryType.REPARATUR);
  const [inspectionType, setInspectionType] = useState(entry?.inspectionType || 'HU');

  // For Edit Mode: Single status/desc
  const [singleDesc, setSingleDesc] = useState(entry?.description || '');
  const [singlePriority, setSinglePriority] = useState<Priority>(entry?.priority || Priority.NORMAL);
  const [singleStatus, setSingleStatus] = useState<'OPEN'|'DONE'>(entry?.status || 'OPEN');
  const [singleMileage, setSingleMileage] = useState(entry?.mileage || '');

  // For Batch Mode: List of items
  const [batchItems, setBatchItems] = useState<{description: string, priority: Priority}[]>([
      { description: '', priority: Priority.NORMAL }
  ]);

  if (!isOpen) return null;

  const handleSave = () => {
    if (isEditMode) {
        // Update single existing entry
        onSave([{
            id: entry.id,
            vehicleId: commonVehicle,
            type: commonType,
            dateAdded: commonDate,
            description: singleDesc,
            priority: singlePriority,
            status: singleStatus,
            mileage: singleStatus === 'DONE' ? (parseInt(singleMileage) || 0) : null,
            inspectionType: commonType === EntryType.PRUEFUNG ? inspectionType : null,
            dateCompleted: singleStatus === 'DONE' ? getTodayDate() : null
        }]);
    } else {
        // Create multiple entries
        const validItems = batchItems.filter(i => i.description.trim() !== '');
        if (validItems.length === 0) {
            alert('Bitte mindestens eine Beschreibung eingeben.');
            return;
        }

        const newEntries = validItems.map(item => ({
            vehicleId: commonVehicle,
            type: commonType,
            dateAdded: commonDate,
            description: item.description,
            priority: item.priority,
            status: 'OPEN',
            inspectionType: commonType === EntryType.PRUEFUNG ? inspectionType : null,
        }));
        onSave(newEntries);
    }
  };

  const handleDelete = () => {
      onDelete(entry.id);
      onClose();
  };

  // Helper for batch list
  const updateBatchItem = (index: number, field: string, val: any) => {
      const newItems = [...batchItems];
      // @ts-ignore
      newItems[index][field] = val;
      setBatchItems(newItems);
  };
  const addBatchRow = () => setBatchItems([...batchItems, { description: '', priority: Priority.NORMAL }]);
  const removeBatchRow = (index: number) => {
      if (batchItems.length > 1) {
          setBatchItems(batchItems.filter((_, i) => i !== index));
      }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded shadow-lg w-full max-w-2xl p-6 max-h-screen overflow-y-auto">
        <h2 className="text-xl font-bold mb-4">{isEditMode ? 'Eintrag bearbeiten' : 'Neuer Eintrag'}</h2>

        {/* COMMON HEADER */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4 bg-gray-50 p-3 rounded">
           <div>
            <label className="block text-xs font-bold mb-1">Datum</label>
            <input type="date" className="w-full border p-2 rounded text-sm" value={commonDate} onChange={e => setCommonDate(e.target.value)} />
          </div>
          <div>
            <label className="block text-xs font-bold mb-1">Fahrzeug</label>
            <select className="w-full border p-2 rounded text-sm" value={commonVehicle} onChange={e => setCommonVehicle(e.target.value)}>
               {vehicles.map((v:any) => <option key={v.id} value={v.id}>{v.licensePlate}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-xs font-bold mb-1">Art</label>
            <select className="w-full border p-2 rounded text-sm" value={commonType} onChange={e => setCommonType(e.target.value as EntryType)}>
              {Object.values(EntryType).map(t => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>
          {commonType === EntryType.PRUEFUNG && (
             <div className="md:col-span-3">
              <label className="block text-xs font-bold mb-1">Prüfungsart</label>
              <select className="w-full border p-2 rounded text-sm" value={inspectionType} onChange={e => setInspectionType(e.target.value as any)}>
                <option value="HU">Hauptuntersuchung (HU)</option>
                <option value="SP">Sicherheitsprüfung (SP)</option>
                <option value="Tacho">Tachoprüfung</option>
                <option value="UVV">UVV</option>
              </select>
            </div>
          )}
        </div>

        {/* CONTENT AREA */}
        <div className="space-y-4">

            {/* EDIT MODE: Single Item */}
            {isEditMode ? (
                <div className="space-y-3 border p-4 rounded">
                     <div>
                        <label className="block text-sm font-bold mb-1">Beschreibung</label>
                        <textarea className="w-full border p-2 rounded" rows={3} value={singleDesc} onChange={e => setSingleDesc(e.target.value)} />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-bold mb-1">Priorität</label>
                            <select className="w-full border p-2 rounded" value={singlePriority} onChange={e => setSinglePriority(e.target.value as Priority)}>
                                {Object.values(Priority).map(p => <option key={p} value={p}>{p}</option>)}
                            </select>
                        </div>
                        <div className="flex items-end">
                            <label className="flex items-center gap-2 cursor-pointer bg-blue-50 px-4 py-2 rounded border border-blue-200 w-full">
                                <input 
                                    type="checkbox" 
                                    className="w-5 h-5"
                                    checked={singleStatus === 'DONE'} 
                                    onChange={e => setSingleStatus(e.target.checked ? 'DONE' : 'OPEN')} 
                                />
                                <span className="font-bold text-blue-900">Ist erledigt</span>
                            </label>
                        </div>
                    </div>
                    {singleStatus === 'DONE' && (
                        <div>
                            <label className="block text-sm font-bold mb-1">KM-Stand bei Erledigung</label>
                            <input type="number" className="w-full border p-2 rounded" value={singleMileage} onChange={e => setSingleMileage(e.target.value)} />
                        </div>
                    )}
                </div>
            ) : (
                // BATCH MODE: Multiple Items
                <div className="space-y-2">
                    <label className="block text-sm font-bold mb-1">Aufgaben / Reparaturen</label>
                    {batchItems.map((item, idx) => (
                        <div key={idx} className="flex gap-2 items-start">
                            <div className="flex-1">
                                <input 
                                    className="w-full border p-2 rounded" 
                                    placeholder="Beschreibung..." 
                                    value={item.description} 
                                    onChange={e => updateBatchItem(idx, 'description', e.target.value)}
                                />
                            </div>
                            <div className="w-32">
                                <select 
                                    className="w-full border p-2 rounded" 
                                    value={item.priority}
                                    onChange={e => updateBatchItem(idx, 'priority', e.target.value)}
                                >
                                     {Object.values(Priority).map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                            {batchItems.length > 1 && (
                                <button onClick={() => removeBatchRow(idx)} className="p-2 text-red-500 hover:bg-red-50 rounded mt-0.5">
                                    <Icons.Trash />
                                </button>
                            )}
                        </div>
                    ))}
                    <button onClick={addBatchRow} className="text-sm text-blue-600 hover:underline flex items-center gap-1 mt-2">
                        <Icons.Plus /> Weitere Zeile hinzufügen
                    </button>
                </div>
            )}
        </div>

        {/* FOOTER */}
        <div className="flex justify-between items-center mt-6 pt-4 border-t">
          {isEditMode ? (
              <button onClick={handleDelete} className="text-red-600 px-4 py-2 rounded hover:bg-red-50 flex items-center gap-2">
                  <Icons.Trash /> Löschen
              </button>
          ) : <div></div>}

          <div className="flex gap-2">
             <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">Abbrechen</button>
             <button onClick={handleSave} className="px-6 py-2 bg-primary text-white rounded hover:bg-blue-700 font-bold">Speichern</button>
          </div>
        </div>
      </div>
    </div>
  );
};

