        <div className="flex justify-between items-center mt-6">
          {order && onDelete ? (
            <button onClick={handleDelete} className="text-red-600 hover:bg-red-50 px-3 py-2 rounded flex items-center gap-1">
               <Icons.Trash /> <span className="text-sm">Löschen</span>
            </button>
          ) : <div></div>}

          <div className="flex justify-end gap-2">
            <button onClick={onClose} className="px-4 py-2 text-gray-600">Abbrechen</button>
            <button onClick={() => onSave(form)} className="px-4 py-2 bg-primary text-white rounded">Speichern</button>
          </div>
        </div>
      </div>
    </div>
  );
}

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { createRoot } from 'react-dom/client';

// --- TYPES & ENUMS ---

enum VehicleType {
  PKW = 'PKW',
  LKW = 'LKW',
  AUFLIEGER = 'Auflieger',
  ANHAENGER = 'Anhänger',
  MASCHINE = 'Maschine',
}

enum EntryType {
  REPARATUR = 'Reparatur',
  WARTUNG = 'Wartung',
  PRUEFUNG = 'Prüfung',
}

enum Priority {
  LOW = 'Niedrig',
  NORMAL = 'Normal',
  HIGH = 'Dringend',
}

enum OrderStatus {
  OFFEN = 'Offen',
  BESTELLT = 'Bestellt',
  ERLEDIGT = 'Erledigt',
}

interface Vehicle {
  id: string;
  licensePlate: string;
  type: VehicleType;
  manufacturer: string;
  model: string; // Typ
  vin: string;
  year: number;
  notes: string;
  coupledVehicleId?: string | null; // For LKW <-> Auflieger

  // Inspection Due Dates (MM/YYYY)
  nextHU?: string;
  nextSP?: string;
  nextUVV?: string;
  nextTacho?: string;

  currentMileage?: number; // KM or Hours
}

interface LogEntry {
  id: string;
  vehicleId: string;
  type: EntryType;
  description: string;
  priority: Priority;
  dateAdded: string; // ISO Date
  dateCompleted?: string;
  status: 'OPEN' | 'DONE';
  mileage?: number;

  // Specific for inspections
  inspectionType?: 'HU' | 'SP' | 'UVV' | 'Tacho';
}

interface Order {
  id: string;
  description: string;
  vehicleId?: string;
  dateAdded: string;
  status: OrderStatus;
}

