       if (method === 'GET') return mockDB.get(collection);
       // @ts-ignore
       if (method === 'POST') return mockDB.post(collection, data);
       // @ts-ignore
       if (method === 'PUT') return mockDB.put(collection, id, data);
       // @ts-ignore
       if (method === 'DELETE') return mockDB.delete(collection, id);
    }

    try {
      const opts: any = { method, headers: { 'Content-Type': 'application/json' } };
      if (data) opts.body = JSON.stringify(data);

      const res = await fetch(`/api${endpoint}`, opts);
      if (!res.ok) throw new Error('API Error');
      return await res.json();
    } catch (e) {
      if (!isOfflineMode) {
        console.warn('Backend unavailable, switching to Offline Mode (LocalStorage).');
        isOfflineMode = true;
      }
      // Retry with MockDB immediately
      return api.request(method, endpoint, data);
    }
  },

  get: (url: string) => api.request('GET', url),
  post: (url: string, data: any) => api.request('POST', url, data),
  put: (url: string, data: any) => api.request('PUT', url, data),
  delete: (url: string) => api.request('DELETE', url)
};

// --- MAIN APPLICATION ---

const App = () => {
  const [activeTab, setActiveTab] = useState('todo');

  // App Data State
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);

  // Instead of blocking error, we track if we are offline
  const [appIsOffline, setAppIsOffline] = useState(false);

  // Admin Mode
  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');

  // Modals
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [editingVehicle, setEditingVehicle] = useState<Vehicle | null>(null);

  const [showEntryModal, setShowEntryModal] = useState(false);
  const [editingEntry, setEditingEntry] = useState<LogEntry | null>(null);

  const [showOrderModal, setShowOrderModal] = useState(false);
  const [editingOrder, setEditingOrder] = useState<Order | null>(null);

  const [showInspectionCompleteModal, setShowInspectionCompleteModal] = useState(false);
  const [completingInspection, setCompletingInspection] = useState<{entry: LogEntry, newDate: string} | null>(null);

  // --- DATA LOADING ---
  const refreshData = useCallback(async () => {
    setLoading(true);
    try {
      // Force checking backend first time, or continue offline if set
      const vData = await api.get('/vehicles');
      const lData = await api.get('/logs');
      const oData = await api.get('/orders');

      setVehicles(vData);
      setLogs(lData);
      setOrders(oData);

      // Update UI state based on api internal flag
      setAppIsOffline(isOfflineMode);
    } catch (e: any) {
      console.error("Critical Error", e);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refreshData();
  }, [refreshData]);

  const handleAdminLogin = () => {
    if (adminPassword === 'Co33ing#admin') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setAdminPassword('');
    } else {
      alert('Falsches Passwort!');
    }
  };

  // --- LOGIC: VEHICLE ---
  const handleSaveVehicle = async (v: Vehicle) => {
    try {
      // Coupling Logic Check
      if (v.type === VehicleType.LKW && v.coupledVehicleId) {
        const existingCoupling = vehicles.find(
          other => other.id !== v.id && other.type === VehicleType.LKW && other.coupledVehicleId === v.coupledVehicleId
        );
        if (existingCoupling) {
          if (!window.confirm(`Der Auflieger ist bereits mit ${existingCoupling.licensePlate} gekoppelt. Verbindung lösen?`)) return;
          // Uncouple old
          await api.put(`/vehicles/${existingCoupling.id}`, { ...existingCoupling, coupledVehicleId: null });
        }
      }

      if (v.id) {
        await api.put(`/vehicles/${v.id}`, v);
      } else {
        await api.post('/vehicles', v);
      }
      refreshData();
      setShowVehicleModal(false);
      setEditingVehicle(null);
    } catch (e: any) {
      alert(`Fehler beim Speichern: ${e.message}`);
    }
  };

  const deleteVehicle = async (id: string) => {
    if (confirm('Fahrzeug wirklich löschen?')) {
      try {
        await api.delete(`/vehicles/${id}`);
        refreshData();
      } catch (e: any) {
        alert(`Löschen fehlgeschlagen: ${e.message}`);
      }
    }
  };

  // --- LOGIC: ENTRIES ---
  const handleSaveEntries = async (entries: Partial<LogEntry>[]) => {
    try {
      // Process serially or parallel
      for (const entry of entries) {
        if (entry.id) {
          await api.put(`/logs/${entry.id}`, entry);
        } else {
          await api.post('/logs', entry);
        }
      }
      refreshData();
      setShowEntryModal(false);
      setEditingEntry(null);
    } catch (e: any) {
      alert(`Fehler beim Speichern: ${e.message}`);
    }
  };

  const handleCompleteEntry = async (entry: LogEntry) => {
    if (entry.type === EntryType.PRUEFUNG && entry.inspectionType) {
      setCompletingInspection({ entry, newDate: '' });
      setShowInspectionCompleteModal(true);
    } else {
      try {
        await api.put(`/logs/${entry.id}`, { ...entry, status: 'DONE', dateCompleted: getTodayDate() });
        refreshData();
      } catch (e: any) {
        alert(`Fehler beim Abschließen: ${e.message}`);
      }
    }
  };

  const confirmInspectionCompletion = async () => {
    if (!completingInspection || !isValidDateMMYYYY(completingInspection.newDate)) {
      alert('Bitte gültiges Datum (MM/YYYY)');
      return;
    }
    const { entry, newDate } = completingInspection;

    try {
      // 1. Update Vehicle Date
      const vehicle = vehicles.find(v => v.id === entry.vehicleId);
      if (vehicle) {
        const updates: any = {};
        if (entry.inspectionType === 'HU') updates.nextHU = newDate;
        if (entry.inspectionType === 'SP') updates.nextSP = newDate;
        if (entry.inspectionType === 'UVV') updates.nextUVV = newDate;
        if (entry.inspectionType === 'Tacho') updates.nextTacho = newDate;

        await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, ...updates });
      }

      // 2. Complete Log
      await api.put(`/logs/${entry.id}`, { ...entry, status: 'DONE', dateCompleted: getTodayDate() });

      refreshData();
      setShowInspectionCompleteModal(false);
      setCompletingInspection(null);
    } catch (e: any) {
      alert(`Fehler: ${e.message}`);
    }
  };

  const deleteLog = async (id: string, skipConfirm = false) => {
    if (skipConfirm || confirm('Eintrag löschen?')) {
      try {
        await api.delete(`/logs/${id}`);
        refreshData();
      } catch (e: any) {
        alert(`Löschen fehlgeschlagen: ${e.message}`);
      }
    }
  };

  // --- LOGIC: ORDERS ---
  const handleSaveOrder = async (formData: Partial<Order>) => {
    try {
      if (formData.id) {
        await api.put(`/orders/${formData.id}`, formData);
      } else {
        await api.post('/orders', formData);
      }
      refreshData();
      setShowOrderModal(false);
      setEditingOrder(null);
    } catch (e: any) { alert(`Fehler beim Speichern: ${e.message}`); }
  };

  const updateOrderStatus = async (id: string, status: OrderStatus) => {
    const order = orders.find(o => o.id === id);
    if(order) {
        try {
          await api.put(`/orders/${id}`, { ...order, status });
          refreshData();
        } catch (e: any) {
          alert(`Fehler beim Aktualisieren: ${e.message}`);
        }
    }
  };

  const deleteOrder = async (id: string, skipConfirm: boolean = false) => {
    if(!skipConfirm && !confirm('Bestellung wirklich löschen?')) return;
    try {
      await api.delete(`/orders/${id}`);
      refreshData();
    } catch (e: any) {
      alert(`Löschen fehlgeschlagen: ${e.message}`);
    }
  }

  // --- RENDER ---

  if (loading && vehicles.length === 0) {
    return <div className="flex h-screen items-center justify-center">Lade Daten...</div>;
  }

  return (
    <div className="flex h-screen flex-col md:flex-row font-sans">
      {/* SIDEBAR NAVIGATION */}
      <div className="w-full md:w-64 bg-slate-800 text-white flex-shrink-0 flex flex-col no-print">
        <div className="p-4 font-bold text-xl border-b border-slate-700">Fuhrpark Manager</div>
        <nav className="flex-1 p-2 space-y-1">
          {[
            { id: 'todo', label: 'ToDo', icon: Icons.Dashboard },
            { id: 'termine', label: 'Prüftermine', icon: Icons.Calendar },
            { id: 'bestellungen', label: 'Bestellliste', icon: Icons.ShoppingCart },
            { id: 'fahrzeuge', label: 'Fahrzeugstamm', icon: Icons.Truck },
            { id: 'historie', label: 'Historie & Suche', icon: Icons.History },
          ].map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded text-left transition-colors ${activeTab === item.id ? 'bg-primary text-white' : 'text-slate-300 hover:bg-slate-700'}`}
            >
              <item.icon />
              {item.label}
            </button>
          ))}
        </nav>

        {/* OFFLINE INDICATOR */}
        {appIsOffline && (
           <div className="p-3 bg-amber-600 text-white text-xs font-bold flex items-center gap-2 mx-2 mb-2 rounded">
             <Icons.WifiOff />
             <div>
               Offline Modus
               <div className="font-normal opacity-75 text-[10px]">Daten werden im Browser gespeichert.</div>
             </div>
           </div>
        )}

        <div className="p-4 border-t border-slate-700 text-xs text-slate-500 flex justify-between items-center">
          <span>v2.1 (PWA Ready)</span>
          <button onClick={() => setShowAdminLogin(true)} className="opacity-50 hover:opacity-100">
            <Icons.Lock />
          </button>
        </div>
      </div>

      {/* MAIN CONTENT AREA */}
      <main className="flex-1 overflow-auto bg-gray-50 p-4 md:p-8 relative">

        {/* --- DASHBOARD --- */}
        {activeTab === 'todo' && (
          <DashboardView 
            logs={logs} 
            vehicles={vehicles} 
            onComplete={handleCompleteEntry}
            onEdit={(l: LogEntry) => { setEditingEntry(l); setShowEntryModal(true); }}
            onDelete={deleteLog}
            onAdd={() => { setEditingEntry(null); setShowEntryModal(true); }}
          />
        )}

        {/* --- FAHRZEUGE --- */}
        {activeTab === 'fahrzeuge' && (
          <VehicleListView 
            vehicles={vehicles} 
            onEdit={(v: Vehicle) => { setEditingVehicle(v); setShowVehicleModal(true); }}
            onDelete={deleteVehicle}
            onAdd={() => { setEditingVehicle(null); setShowVehicleModal(true); }}
          />
        )}

        {/* --- TERMINE --- */}
        {activeTab === 'termine' && (
          <AppointmentsView vehicles={vehicles} />
        )}

        {/* --- BESTELLUNGEN --- */}
        {activeTab === 'bestellungen' && (
          <OrdersView 
            orders={orders} 
            vehicles={vehicles}
            onAdd={() => { setEditingOrder(null); setShowOrderModal(true); }}
            onEdit={(o: Order) => { setEditingOrder(o); setShowOrderModal(true); }}
            onStatusChange={updateOrderStatus}
            onDelete={deleteOrder}
          />
        )}

        {/* --- HISTORIE --- */}
        {activeTab === 'historie' && (
          <HistoryView 
            logs={logs} 
            vehicles={vehicles} 
            isAdmin={isAdmin}
            onEdit={(l: LogEntry) => { setEditingEntry(l); setShowEntryModal(true); }}
            onDelete={deleteLog}
          />
        )}

      </main>

      {/* --- MODALS --- */}

      {/* Vehicle Modal */}
      {showVehicleModal && (
        <VehicleModal 
          isOpen={showVehicleModal} 
          onClose={() => setShowVehicleModal(false)}
          vehicle={editingVehicle}
          allVehicles={vehicles}
          onSave={handleSaveVehicle}
        />
      )}

      {/* Entry Modal */}
      {showEntryModal && (
        <EntryModal 
          isOpen={showEntryModal}
          onClose={() => setShowEntryModal(false)}
          entry={editingEntry}
          vehicles={vehicles}
          onSave={handleSaveEntries}
          onDelete={deleteLog}
        />
      )}

      {/* Order Modal */}
      {showOrderModal && (
        <OrderModal
          isOpen={showOrderModal}
          onClose={() => setShowOrderModal(false)}
          order={editingOrder}
          vehicles={vehicles}
          onSave={handleSaveOrder}
          onDelete={deleteOrder}
        />
      )}

      {/* Admin Login Modal */}
      {showAdminLogin && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded shadow-lg w-80">
            <h3 className="text-lg font-bold mb-4">Admin Login</h3>
            <input 
              type="password" 
              className="w-full border p-2 rounded mb-4" 
              placeholder="Passwort"
              value={adminPassword}
              onChange={e => setAdminPassword(e.target.value)}
            />
            <div className="flex justify-end gap-2">
              <button onClick={() => setShowAdminLogin(false)} className="px-4 py-2 text-gray-600">Abbrechen</button>
              <button onClick={handleAdminLogin} className="px-4 py-2 bg-primary text-white rounded">Login</button>
            </div>
          </div>
        </div>
      )}

      {/* Inspection Complete Modal */}
      {showInspectionCompleteModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded shadow-lg w-96">
            <h3 className="text-lg font-bold mb-4">Prüfung abgeschlossen</h3>
            <p className="mb-2 text-sm text-gray-600">Bitte neuen Termin für {completingInspection?.entry.inspectionType} eingeben:</p>
            <input 
              type="text" 
              className="w-full border p-2 rounded mb-4" 
              placeholder="MM/YYYY"
              value={completingInspection?.newDate || ''}
              onChange={e => setCompletingInspection(prev => prev ? {...prev, newDate: e.target.value} : null)}
            />
            <div className="flex justify-end gap-2">
              <button onClick={() => setShowInspectionCompleteModal(false)} className="px-4 py-2 text-gray-600">Abbrechen</button>
              <button onClick={confirmInspectionCompletion} className="px-4 py-2 bg-green-600 text-white rounded">Bestätigen & Speichern</button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

// --- SUB-VIEWS ---

const DashboardView = ({ logs, vehicles, onComplete, onEdit, onDelete, onAdd }: any) => {
  const [filterType, setFilterType] = useState('');
  const [filterVehicle, setFilterVehicle] = useState('');
  const [filterPriority, setFilterPriority] = useState('');
  const [showDone, setShowDone] = useState(false);

  // Create virtual entries for dashboard from due dates
  const dueInspections = useMemo(() => {
    const alerts: any[] = [];
    vehicles.forEach((v: Vehicle) => {
      const check = (date: string | undefined, type: string) => {
        if (!date) return;
        const parts = date.split('/');
        if (parts.length !== 2) return;
        const [m, y] = parts.map(Number);
        if (isNaN(m) || isNaN(y)) return;

        const due = new Date(y, m - 1); // 1st of that month
        const now = new Date();
        // Show if due within next 30 days or overdue
        if (due.getTime() < now.getTime() + 30 * 24 * 60 * 60 * 1000) {
          alerts.push({
            id: `sys_${v.id}_${type}`,
            vehicleId: v.id,
            type: EntryType.PRUEFUNG,
            inspectionType: type,
            description: `Fällige ${type}: ${date}`,
            priority: Priority.HIGH,
            dateAdded: getTodayDate(),
            status: 'OPEN',
            isSystem: true,
            rawDate: date
          });
        }
      };
      check(v.nextHU, 'HU');
      check(v.nextSP, 'SP');
      check(v.nextUVV, 'UVV');
      check(v.nextTacho, 'Tacho');
    });
    return alerts;
  }, [vehicles]);

  const filteredLogs = [...logs, ...dueInspections].filter((l: any) => {
    if (!showDone && l.status === 'DONE') return false;
    if (showDone && l.status !== 'DONE') return false;
    if (filterType && l.type !== filterType) return false;
    if (filterVehicle && l.vehicleId !== filterVehicle) return false;
    if (filterPriority && l.priority !== filterPriority) return false;
    return true;
  }).sort((a, b) => {
    // Sort logic: HIGH Priority first, then System alerts, then Date
    const priorityScore = (p: Priority) => p === Priority.HIGH ? 3 : p === Priority.NORMAL ? 2 : 1;
    const scoreA = priorityScore(a.priority || Priority.NORMAL);
    const scoreB = priorityScore(b.priority || Priority.NORMAL);

    if (scoreA !== scoreB) return scoreB - scoreA;
    if (a.isSystem !== b.isSystem) return a.isSystem ? -1 : 1;

    return a.vehicleId.localeCompare(b.vehicleId);
  });

  const getPriorityColor = (p: Priority) => {
    switch (p) {
      case Priority.HIGH: return 'bg-red-100 text-red-800 border-red-200';
      case Priority.LOW: return 'bg-gray-100 text-gray-800 border-gray-200';
      default: return 'bg-blue-50 text-blue-800 border-blue-200';
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded shadow no-print">
        <h2 className="text-2xl font-bold text-gray-800">ToDo Liste</h2>
        <div className="flex flex-wrap gap-2 items-center">
          <select className="border p-2 rounded text-sm" value={filterVehicle} onChange={e => setFilterVehicle(e.target.value)}>
            <option value="">Alle Fahrzeuge</option>
            {vehicles.map((v: any) => <option key={v.id} value={v.id}>{v.licensePlate}</option>)}
          </select>
          <select className="border p-2 rounded text-sm" value={filterType} onChange={e => setFilterType(e.target.value)}>
            <option value="">Alle Typen</option>
            {Object.values(EntryType).map(t => <option key={t} value={t}>{t}</option>)}
          </select>
          <select className="border p-2 rounded text-sm" value={filterPriority} onChange={e => setFilterPriority(e.target.value)}>
            <option value="">Alle Prioritäten</option>
            {Object.values(Priority).map(p => <option key={p} value={p}>{p}</option>)}
          </select>
          <label className="flex items-center gap-2 text-sm bg-gray-50 px-2 py-2 rounded border">
            <input type="checkbox" checked={showDone} onChange={e => setShowDone(e.target.checked)} />
            Erledigte
          </label>
          <button onClick={onAdd} className="bg-primary hover:bg-blue-700 text-white px-4 py-2 rounded flex items-center gap-2 shadow-sm">
            <Icons.Plus /> Eintrag
          </button>
        </div>
      </div>

      <div className="bg-white rounded shadow overflow-hidden">
        <table className="w-full text-left border-collapse">
          <thead className="bg-gray-100 text-gray-600 uppercase text-sm">
            <tr>
              <th className="p-3">Kennzeichen</th>
              <th className="p-3">Prio</th>
              <th className="p-3">Typ</th>
              <th className="p-3">Beschreibung</th>
              <th className="p-3">Datum</th>
              <th className="p-3 text-right">Status</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {filteredLogs.length === 0 && (
              <tr><td colSpan={6} className="p-8 text-center text-gray-400">Keine Einträge vorhanden.</td></tr>
            )}
            {filteredLogs.map((l: any) => {
              const vehicle = vehicles.find((v: any) => v.id === l.vehicleId);
              const label = vehicle ? (
                  <span>
                    {vehicle.licensePlate} 
                    {vehicle.type === VehicleType.LKW && vehicle.coupledVehicleId && (
                      <span className="text-xs text-gray-500 ml-1">
                         [{vehicles.find((x:any) => x.id === vehicle.coupledVehicleId)?.licensePlate}]
                      </span>
                    )}
                  </span>
                ) : '???';

              return (
                <tr 
                  key={l.id} 
                  className={`hover:bg-gray-50 cursor-pointer transition-colors ${l.isSystem ? 'bg-red-50' : ''}`}
                  onClick={() => !l.isSystem && onEdit(l)}
                >
                  <td className="p-3 font-medium">{label}</td>
                  <td className="p-3">
                    <span className={`px-2 py-1 rounded text-xs border ${getPriorityColor(l.priority)}`}>
                      {l.priority || Priority.NORMAL}
                    </span>
                  </td>
                  <td className="p-3">
                    <span className={`px-2 py-1 rounded text-xs text-white ${l.type === EntryType.REPARATUR ? 'bg-red-500' : l.type === EntryType.WARTUNG ? 'bg-orange-500' : 'bg-blue-500'}`}>
                      {l.type}
                    </span>
                    {l.isSystem && <span className="ml-2 text-red-600 text-xs font-bold">AUTO</span>}
                  </td>
                  <td className="p-3">{l.description}</td>
                  <td className="p-3 text-sm text-gray-500">{l.dateAdded}</td>
                  <td className="p-3 text-right" onClick={(e) => e.stopPropagation()}>
                    {l.status === 'OPEN' && (
                      <button 
                        onClick={() => onComplete(l)} 
                        title="Erledigt markieren"
                        className="p-1 text-green-600 hover:bg-green-100 rounded border border-transparent hover:border-green-200"
                      >
                        <Icons.Check />
                      </button>
                    )}
                    {l.status === 'DONE' && <span className="text-green-600 font-bold text-xs">ERLEDIGT</span>}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

