const AppointmentsView = ({ vehicles }: any) => {
  const getDueStatus = (date?: string) => {
    if (!date) return 'text-gray-400';
    const parts = date.split('/');
    if (parts.length !== 2) return 'text-gray-400';
    const [m, y] = parts.map(Number);
    if(isNaN(m) || isNaN(y)) return 'text-gray-400';

    const due = new Date(y, m - 1);
    const now = new Date();
    if (due < now) return 'text-red-600 font-bold bg-red-100 px-1 rounded'; // Overdue
    if (due.getTime() < now.getTime() + 60 * 24 * 60 * 60 * 1000) return 'text-orange-600 font-bold'; // Due soon
    return 'text-green-600';
  };

  // Sort by next critical date (simplified logic)
  const sorted = [...vehicles].sort((a, b) => a.licensePlate.localeCompare(b.licensePlate));

  return (
    <div className="space-y-4">
      <div className="bg-white p-4 rounded shadow flex justify-between">
        <h2 className="text-2xl font-bold text-gray-800">Prüftermine</h2>
        <button onClick={() => window.print()} className="bg-secondary text-white px-4 py-2 rounded flex items-center gap-2 no-print">
          <Icons.Printer /> Drucken
        </button>
      </div>

      <div className="bg-white rounded shadow overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead className="bg-gray-100 text-gray-600 uppercase text-sm">
            <tr>
              <th className="p-3">Kennzeichen</th>
              <th className="p-3">Typ</th>
              <th className="p-3">HU</th>
              <th className="p-3">SP</th>
              <th className="p-3">UVV</th>
              <th className="p-3">Tacho</th>
              <th className="p-3">Gekoppelt</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {sorted.map((v: Vehicle) => (
              <tr key={v.id} className="hover:bg-gray-50">
                <td className="p-3 font-bold">{v.licensePlate}</td>
                <td className="p-3 text-sm">{v.type}</td>
                <td className={`p-3 ${getDueStatus(v.nextHU)}`}>{v.nextHU || '-'}</td>
                <td className={`p-3 ${getDueStatus(v.nextSP)}`}>{v.nextSP || '-'}</td>
                <td className={`p-3 ${getDueStatus(v.nextUVV)}`}>{v.nextUVV || '-'}</td>
