const DashboardView = ({ logs, vehicles, onComplete, onEdit, onDelete, onAdd }: any) => {
  const [filterType, setFilterType] = useState('');
  const [filterVehicle, setFilterVehicle] = useState('');
  const [filterPriority, setFilterPriority] = useState('');
  const [showDone, setShowDone] = useState(false);

  // Create virtual entries for dashboard from due dates
  const dueInspections = useMemo(() => {
    const alerts: any[] = [];
    vehicles.forEach((v: Vehicle) => {
      const check = (date: string | undefined, type: string) => {
        if (!date) return;
        const parts = date.split('/');
        if (parts.length !== 2) return;
        const [m, y] = parts.map(Number);
        if (isNaN(m) || isNaN(y)) return;

        const due = new Date(y, m - 1); // 1st of that month
        const now = new Date();
        // Show if due within next 30 days or overdue
        if (due.getTime() < now.getTime() + 30 * 24 * 60 * 60 * 1000) {
          alerts.push({
            id: `sys_${v.id}_${type}`,
            vehicleId: v.id,
            type: EntryType.PRUEFUNG,
            inspectionType: type,
            description: `Fällige ${type}: ${date}`,
            priority: Priority.HIGH,
            dateAdded: getTodayDate(),
            status: 'OPEN',
            isSystem: true,
            rawDate: date
          });
        }
      };
      check(v.nextHU, 'HU');
      check(v.nextSP, 'SP');
      check(v.nextUVV, 'UVV');
      check(v.nextTacho, 'Tacho');
    });
    return alerts;
  }, [vehicles]);

  const filteredLogs = [...logs, ...dueInspections].filter((l: any) => {
    if (!showDone && l.status === 'DONE') return false;
    if (showDone && l.status !== 'DONE') return false;
    if (filterType && l.type !== filterType) return false;
    if (filterVehicle && l.vehicleId !== filterVehicle) return false;
    if (filterPriority && l.priority !== filterPriority) return false;
    return true;
  }).sort((a, b) => {
    // Sort logic: HIGH Priority first, then System alerts, then Date
    const priorityScore = (p: Priority) => p === Priority.HIGH ? 3 : p === Priority.NORMAL ? 2 : 1;
    const scoreA = priorityScore(a.priority || Priority.NORMAL);
    const scoreB = priorityScore(b.priority || Priority.NORMAL);

    if (scoreA !== scoreB) return scoreB - scoreA;
    if (a.isSystem !== b.isSystem) return a.isSystem ? -1 : 1;

    return a.vehicleId.localeCompare(b.vehicleId);
  });

  const getPriorityColor = (p: Priority) => {
    switch (p) {
      case Priority.HIGH: return 'bg-red-100 text-red-800 border-red-200';
      case Priority.LOW: return 'bg-gray-100 text-gray-800 border-gray-200';
      default: return 'bg-blue-50 text-blue-800 border-blue-200';
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded shadow no-print">
        <h2 className="text-2xl font-bold text-gray-800">ToDo Liste</h2>
        <div className="flex flex-wrap gap-2 items-center">
          <select className="border p-2 rounded text-sm" value={filterVehicle} onChange={e => setFilterVehicle(e.target.value)}>
            <option value="">Alle Fahrzeuge</option>
            {vehicles.map((v: any) => <option key={v.id} value={v.id}>{v.licensePlate}</option>)}
          </select>
          <select className="border p-2 rounded text-sm" value={filterType} onChange={e => setFilterType(e.target.value)}>
            <option value="">Alle Typen</option>
            {Object.values(EntryType).map(t => <option key={t} value={t}>{t}</option>)}
          </select>
          <select className="border p-2 rounded text-sm" value={filterPriority} onChange={e => setFilterPriority(e.target.value)}>
            <option value="">Alle Prioritäten</option>
            {Object.values(Priority).map(p => <option key={p} value={p}>{p}</option>)}
          </select>
          <label className="flex items-center gap-2 text-sm bg-gray-50 px-2 py-2 rounded border">
            <input type="checkbox" checked={showDone} onChange={e => setShowDone(e.target.checked)} />
            Erledigte
          </label>
          <button onClick={onAdd} className="bg-primary hover:bg-blue-700 text-white px-4 py-2 rounded flex items-center gap-2 shadow-sm">
            <Icons.Plus /> Eintrag
          </button>
        </div>
      </div>

      <div className="bg-white rounded shadow overflow-hidden">
        <table className="w-full text-left border-collapse">
          <thead className="bg-gray-100 text-gray-600 uppercase text-sm">
            <tr>
              <th className="p-3">Kennzeichen</th>
              <th className="p-3">Prio</th>
              <th className="p-3">Typ</th>
              <th className="p-3">Beschreibung</th>
              <th className="p-3">Datum</th>
              <th className="p-3 text-right">Status</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {filteredLogs.length === 0 && (
              <tr><td colSpan={6} className="p-8 text-center text-gray-400">Keine Einträge vorhanden.</td></tr>
            )}
            {filteredLogs.map((l: any) => {
              const vehicle = vehicles.find((v: any) => v.id === l.vehicleId);
              const label = vehicle ? (
                  <span>
                    {vehicle.licensePlate} 
                    {vehicle.type === VehicleType.LKW && vehicle.coupledVehicleId && (
                      <span className="text-xs text-gray-500 ml-1">
                         [{vehicles.find((x:any) => x.id === vehicle.coupledVehicleId)?.licensePlate}]
                      </span>
                    )}
                  </span>
                ) : '???';
              const hasAttachments = l.attachments && l.attachments.length > 0;

              return (
                <tr 
                  key={l.id} 
                  className={`hover:bg-gray-50 cursor-pointer transition-colors ${l.isSystem ? 'bg-red-50' : ''}`}
                  onClick={() => !l.isSystem && onEdit(l)}
                >
                  <td className="p-3 font-medium">{label}</td>
                  <td className="p-3">
                    <span className={`px-2 py-1 rounded text-xs border ${getPriorityColor(l.priority)}`}>
                      {l.priority || Priority.NORMAL}
                    </span>
                  </td>
                  <td className="p-3">
                    <span className={`px-2 py-1 rounded text-xs text-white ${l.type === EntryType.REPARATUR ? 'bg-red-500' : l.type === EntryType.WARTUNG ? 'bg-orange-500' : 'bg-blue-500'}`}>
                      {l.type}
                    </span>
                    {l.isSystem && <span className="ml-2 text-red-600 text-xs font-bold">AUTO</span>}
                  </td>
                  <td className="p-3">
                    <div className="flex items-center gap-2">
                        {l.description}
                        {hasAttachments && <span className="text-gray-400"><Icons.Paperclip /></span>}
                    </div>
                  </td>
                  <td className="p-3 text-sm text-gray-500">{l.dateAdded}</td>
                  <td className="p-3 text-right" onClick={(e) => e.stopPropagation()}>
                    {l.status === 'OPEN' && (
                      <button 
                        onClick={() => onComplete(l)} 
                        title="Erledigt markieren"
                        className="p-1 text-green-600 hover:bg-green-100 rounded border border-transparent hover:border-green-200"
                      >
                        <Icons.Check />
                      </button>
                    )}
                    {l.status === 'DONE' && <span className="text-green-600 font-bold text-xs">ERLEDIGT</span>}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const VehicleListView = ({ vehicles, onAdd, onEdit, onDelete, onImport }: any) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if(!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
       const text = evt.target?.result as string;
       if(!text) return;

       // Simple CSV Parser with better error handling
       try {
           const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
           if(lines.length < 2) throw new Error("Datei ist leer oder hat nur eine Kopfzeile");

           // Detect separator
           const firstLine = lines[0];
           const sep = firstLine.includes(';') ? ';' : ',';

           const headers = lines[0].split(sep).map(h => h.trim().toLowerCase().replace(/"/g, ''));

           // Map Headers
           const getIdx = (candidates: string[]) => headers.findIndex(h => candidates.some(c => h.includes(c)));

           const idxPlate = getIdx(['kennzeichen', 'license', 'plate']);
           const idxType = getIdx(['typ', 'art', 'type']);
           const idxManuf = getIdx(['hersteller', 'marke', 'brand', 'manufacturer']);
           const idxModel = getIdx(['modell', 'model']);
           const idxVin = getIdx(['vin', 'fahrgestell', 'ident']);
           const idxYear = getIdx(['baujahr', 'jahr', 'year']);
           const idxHU = getIdx(['hu', 'hauptunter']);
           const idxSP = getIdx(['sp', 'sicherheits']);

           if (idxPlate === -1) {
               throw new Error("Konnte Spalte 'Kennzeichen' nicht finden.");
           }

           const newVehicles: Partial<Vehicle>[] = [];

           for(let i=1; i<lines.length; i++) {
               const row = lines[i].split(sep).map(c => c.trim().replace(/"/g, ''));
               if(row.length < headers.length * 0.5) continue; // Skip malformed rows

               const plate = row[idxPlate];
               if(!plate) continue;

               // Helper for type
               let typeVal = VehicleType.LKW;
               const rawType = idxType > -1 ? row[idxType].toUpperCase() : '';
               if(rawType.includes('PKW')) typeVal = VehicleType.PKW;
               else if(rawType.includes('AUFLIEGER')) typeVal = VehicleType.AUFLIEGER;
               else if(rawType.includes('ANHÄNGER') || rawType.includes('ANHAENGER')) typeVal = VehicleType.ANHAENGER;
               else if(rawType.includes('MASCHINE')) typeVal = VehicleType.MASCHINE;

               newVehicles.push({
                   licensePlate: plate.toUpperCase(),
                   type: typeVal,
                   manufacturer: idxManuf > -1 ? row[idxManuf] : '',
                   model: idxModel > -1 ? row[idxModel] : '',
                   vin: idxVin > -1 ? row[idxVin] : '',
                   year: idxYear > -1 ? (parseInt(row[idxYear]) || new Date().getFullYear()) : new Date().getFullYear(),
                   notes: 'CSV Import',
                   nextHU: idxHU > -1 ? row[idxHU] : '',
                   nextSP: idxSP > -1 ? row[idxSP] : '',
               });
           }

           if(newVehicles.length > 0) {
               if(confirm(`${newVehicles.length} Fahrzeuge gefunden. Importieren?`)) {
                   onImport(newVehicles);
               }
           } else {
               alert("Keine gültigen Datensätze gefunden.");
           }
       } catch (err: any) {
           alert("Fehler beim Verarbeiten der CSV: " + err.message);
       }

       // Reset input
       if(fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.onerror = () => alert("Fehler beim Lesen der Datei");
    reader.readAsText(file);
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center bg-white p-4 rounded shadow">
        <h2 className="text-2xl font-bold text-gray-800">Fahrzeuge</h2>
        <div className="flex gap-2">
            <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept=".csv,.txt,text/*" 
                onChange={handleFileChange}
            />
            <button 
                onClick={() => fileInputRef.current?.click()} 
                className="bg-secondary hover:bg-slate-600 text-white px-4 py-2 rounded flex items-center gap-2"
                title="CSV Format: Kennzeichen; Typ; Hersteller; Modell..."
            >
                <Icons.Upload /> CSV Import
            </button>
            <button onClick={onAdd} className="bg-primary hover:bg-blue-700 text-white px-4 py-2 rounded flex items-center gap-2">
                <Icons.Plus /> Fahrzeug anlegen
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {vehicles.map((v: Vehicle) => (
          <div key={v.id} className="bg-white p-4 rounded shadow card">
            <div className="flex justify-between items-start mb-2">
              <div>
                <h3 className="text-xl font-bold">{v.licensePlate}</h3>
                <span className="text-xs bg-gray-200 px-2 py-1 rounded">{v.type}</span>
              </div>
              <div className="space-x-1">
                <button onClick={() => onEdit(v)} className="p-1 text-blue-600 hover:bg-blue-50 rounded"><Icons.Edit /></button>
                <button onClick={() => onDelete(v.id)} className="p-1 text-red-600 hover:bg-red-50 rounded"><Icons.Trash /></button>
              </div>
            </div>

            <div className="text-sm text-gray-600 space-y-1 mt-2">
              <p>{v.manufacturer} {v.model}</p>
              <p>VIN: {v.vin}</p>

              {v.type === VehicleType.LKW && v.coupledVehicleId && (
                <p className="font-semibold text-blue-600">
                  Gekoppelt: {vehicles.find((x:any) => x.id === v.coupledVehicleId)?.licensePlate || 'Unbekannt'}
                </p>
              )}

              <div className="border-t pt-2 mt-2 grid grid-cols-2 gap-2">
                {v.nextHU && <div>HU: <span className="font-mono">{v.nextHU}</span></div>}
                {v.nextSP && <div>SP: <span className="font-mono">{v.nextSP}</span></div>}
                {v.nextUVV && <div>UVV: <span className="font-mono">{v.nextUVV}</span></div>}
                {v.nextTacho && <div>Tacho: <span className="font-mono">{v.nextTacho}</span></div>}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

const AppointmentsView = ({ vehicles }: any) => {
  const getDueStatus = (date?: string) => {
    if (!date) return 'text-gray-400';
    const parts = date.split('/');
    if (parts.length !== 2) return 'text-gray-400';
    const [m, y] = parts.map(Number);
    if(isNaN(m) || isNaN(y)) return 'text-gray-400';

    const due = new Date(y, m - 1);
    const now = new Date();
    if (due < now) return 'text-red-600 font-bold bg-red-100 px-1 rounded'; // Overdue
    if (due.getTime() < now.getTime() + 60 * 24 * 60 * 60 * 1000) return 'text-orange-600 font-bold'; // Due soon
    return 'text-green-600';
  };

  // Sort by next critical date (simplified logic)
  const sorted = [...vehicles].sort((a, b) => a.licensePlate.localeCompare(b.licensePlate));

