              <th className="p-3">Fahrzeug</th>
              <th className="p-3">Status</th>
              <th className="p-3 no-print">Aktion</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {orders.map((o: Order) => (
              <tr 
                key={o.id} 
                className={`cursor-pointer hover:bg-gray-100 ${o.status === OrderStatus.ERLEDIGT ? 'bg-gray-50 text-gray-400' : ''}`}
                onClick={() => onEdit(o)}
              >
                <td className="p-3">{o.description}</td>
                <td className="p-3">{o.vehicleId ? vehicles.find((v:any) => v.id === o.vehicleId)?.licensePlate : '-'}</td>
                <td className="p-3">
                  <span className={`px-2 py-1 rounded text-xs text-white ${
                    o.status === OrderStatus.OFFEN ? 'bg-red-500' : o.status === OrderStatus.BESTELLT ? 'bg-yellow-500' : 'bg-green-500'
                  }`}>
                    {o.status}
                  </span>
                </td>
                <td className="p-3 flex gap-2 no-print" onClick={(e) => e.stopPropagation()}>
                  {o.status !== OrderStatus.ERLEDIGT && (
                    <>
                      <button onClick={() => onStatusChange(o.id, OrderStatus.BESTELLT)} className="text-xs bg-blue-100 text-blue-800 px-2 py-1 rounded">Bestellt</button>
                      <button onClick={() => onStatusChange(o.id, OrderStatus.ERLEDIGT)} className="text-xs bg-green-100 text-green-800 px-2 py-1 rounded">Erledigt</button>
                    </>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const HistoryView = ({ logs, vehicles, isAdmin, onEdit, onDelete }: any) => {
  const [term, setTerm] = useState('');
  const [filterVehicleId, setFilterVehicleId] = useState('');
  const [filterType, setFilterType] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');

  const filtered = logs
    .filter((l: any) => l.status === 'DONE')
    .filter((l: any) => {
      // 1. Search Term
      const v = vehicles.find((x:any) => x.id === l.vehicleId);
      const searchStr = `${l.description} ${v?.licensePlate} ${l.type}`.toLowerCase();
      const matchesTerm = !term || searchStr.includes(term.toLowerCase());

      // 2. Vehicle Filter
      const matchesVehicle = !filterVehicleId || l.vehicleId === filterVehicleId;

      // 3. Type Filter
      const matchesType = !filterType || l.type === filterType;

      // 4. Date Filter
      const entryDate = l.dateCompleted || l.dateAdded; // ISO YYYY-MM-DD
      const matchesFrom = !dateFrom || entryDate >= dateFrom;
      const matchesTo = !dateTo || entryDate <= dateTo;

      return matchesTerm && matchesVehicle && matchesType && matchesFrom && matchesTo;
    })
    .sort((a: any, b: any) => new Date(b.dateCompleted || b.dateAdded).getTime() - new Date(a.dateCompleted || a.dateAdded).getTime());

  const activeFiltersCount = [term, filterVehicleId, filterType, dateFrom, dateTo].filter(Boolean).length;

  return (
    <div className="space-y-4">
       <div className="bg-white p-4 rounded shadow flex flex-col gap-4 no-print">
        <div className="flex flex-col md:flex-row justify-between gap-4 items-center">
          <h2 className="text-2xl font-bold text-gray-800">Historie & Suche</h2>
          <div className="flex gap-2 w-full md:w-auto">
             <button onClick={() => window.print()} className="bg-secondary text-white px-4 py-2 rounded flex items-center gap-2">
               <Icons.Printer /> Drucken
            </button>
          </div>
        </div>

        {/* Filter Toolbar */}
        <div className="bg-gray-50 p-4 rounded border border-gray-200 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-3">
          {/* Text Search */}
          <div className="lg:col-span-1">
             <label className="block text-xs font-bold text-gray-500 mb-1">Stichwort</label>
             <input 
              type="text" 
              placeholder="Suche..." 
              className="w-full border p-2 rounded text-sm"
              value={term}
              onChange={e => setTerm(e.target.value)}
            />
          </div>

          {/* Vehicle Filter */}
          <div>
            <label className="block text-xs font-bold text-gray-500 mb-1">Fahrzeug</label>
            <select 
              className="w-full border p-2 rounded text-sm" 
              value={filterVehicleId} 
              onChange={e => setFilterVehicleId(e.target.value)}
            >
              <option value="">Alle Fahrzeuge</option>
              {vehicles.map((v:any) => (
                <option key={v.id} value={v.id}>{v.licensePlate}</option>
              ))}
            </select>
          </div>

          {/* Type Filter */}
          <div>
            <label className="block text-xs font-bold text-gray-500 mb-1">Kategorie</label>
            <select 
              className="w-full border p-2 rounded text-sm" 
              value={filterType} 
              onChange={e => setFilterType(e.target.value)}
            >
              <option value="">Alle Kategorien</option>
              {Object.values(EntryType).map(t => (
                <option key={t} value={t}>{t}</option>
              ))}
            </select>
          </div>

          {/* Date Range */}
          <div>
            <label className="block text-xs font-bold text-gray-500 mb-1">Zeitraum Von</label>
            <input 
              type="date" 
              className="w-full border p-2 rounded text-sm"
              value={dateFrom}
              onChange={e => setDateFrom(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-xs font-bold text-gray-500 mb-1">Zeitraum Bis</label>
            <input 
              type="date" 
              className="w-full border p-2 rounded text-sm"
              value={dateTo}
              onChange={e => setDateTo(e.target.value)}
            />
          </div>
        </div>

        {/* Reset Button */}
        {activeFiltersCount > 0 && (
          <div className="flex justify-end">
            <button 
              onClick={() => {
                setTerm('');
                setFilterVehicleId('');
                setFilterType('');
                setDateFrom('');
                setDateTo('');
              }}
              className="text-sm text-red-600 hover:underline flex items-center gap-1"
            >
              <Icons.Trash /> Filter zurücksetzen
            </button>
          </div>
        )}
      </div>

      <div className="bg-white rounded shadow">
        <table className="w-full text-left border-collapse">
          <thead className="bg-gray-100 text-gray-600 uppercase text-sm">
            <tr>
              <th className="p-3">Datum (Erledigt)</th>
              <th className="p-3">Kennzeichen</th>
              <th className="p-3">Typ</th>
              <th className="p-3">Beschreibung</th>
              <th className="p-3">KM / Std</th>
              {isAdmin && <th className="p-3 no-print">Admin</th>}
            </tr>
          </thead>
          <tbody className="divide-y">
            {filtered.length === 0 && (
              <tr>
                <td colSpan={6} className="p-8 text-center text-gray-400">
                  Keine Ergebnisse für die gewählten Filter.
                </td>
              </tr>
            )}
            {filtered.map((l: any) => {
               const v = vehicles.find((x:any) => x.id === l.vehicleId);
               const hasAttachments = l.attachments && l.attachments.length > 0;
               return (
                <tr key={l.id} className="hover:bg-gray-50">
                  <td className="p-3 text-sm">{l.dateCompleted || l.dateAdded}</td>
                  <td className="p-3 font-medium">{v?.licensePlate || '?'}</td>
                  <td className="p-3"><span className="bg-gray-200 text-xs px-2 py-1 rounded">{l.type}</span></td>
                  <td className="p-3">
                     <div className="flex items-center gap-2">
                        {l.description}
                        {hasAttachments && <span className="text-gray-400" title={`${l.attachments.length} Anhang/Anhänge`}><Icons.Paperclip /></span>}
                    </div>
                  </td>
                  <td className="p-3">{l.mileage || '-'}</td>
                  {isAdmin && (
                    <td className="p-3 no-print flex gap-2">
                      <button onClick={() => onEdit(l)} className="text-blue-600"><Icons.Edit /></button>
                      <button onClick={() => onDelete(l.id)} className="text-red-600"><Icons.Trash /></button>
                    </td>
                  )}
                </tr>
               );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

