        onDelete(order.id, true);
        onClose();
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded shadow-lg w-full max-w-md p-6">
        <h2 className="text-xl font-bold mb-4">{order ? 'Bestellung bearbeiten' : 'Ersatzteil bestellen'}</h2>
        <div className="space-y-4">
           <div>
             <label className="block text-sm font-bold mb-1">Bezeichnung / Teil</label>
             <input className="w-full border p-2 rounded" value={form.description} onChange={e => setForm({...form, description: e.target.value})} />
          </div>
          <div>
            <label className="block text-sm font-bold mb-1">Für Fahrzeug (Optional)</label>
            <select className="w-full border p-2 rounded" value={form.vehicleId || ''} onChange={e => setForm({...form, vehicleId: e.target.value})}>
               <option value="">-- Allgemein / Lager --</option>
               {vehicles.map((v:any) => <option key={v.id} value={v.id}>{v.licensePlate}</option>)}
            </select>
          </div>
          {/* Status Field */}
           <div>
            <label className="block text-sm font-bold mb-1">Status</label>
            <select className="w-full border p-2 rounded" value={form.status || OrderStatus.OFFEN} onChange={e => setForm({...form, status: e.target.value as OrderStatus})}>
               {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
            </select>
          </div>
        </div>

        <div className="flex justify-between items-center mt-6">
          {order && onDelete ? (
            <button onClick={handleDelete} className="text-red-600 hover:bg-red-50 px-3 py-2 rounded flex items-center gap-1">
               <Icons.Trash /> <span className="text-sm">Löschen</span>
            </button>
          ) : <div></div>}

          <div className="flex justify-end gap-2">
            <button onClick={onClose} className="px-4 py-2 text-gray-600">Abbrechen</button>
            <button onClick={() => onSave(form)} className="px-4 py-2 bg-primary text-white rounded">Speichern</button>
          </div>
        </div>
      </div>
    </div>
  );
}

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

