    l.status === 'DONE' && 
    (l.description.toLowerCase().includes(filter.toLowerCase()) || 
     vehicles.find((v:Vehicle) => v.id === l.vehicleId)?.licensePlate.toLowerCase().includes(filter.toLowerCase()))
  );

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">Historie</h2>
