const AppointmentsView = ({ vehicles }: any) => {
  const appointments = useMemo(() => {
    const list: any[] = [];
    vehicles.forEach((v: Vehicle) => {
      if (v.nextHU) list.push({ id: v.id + 'HU', vid: v.id, license: v.licensePlate, type: 'HU', date: v.nextHU });
      if (v.nextSP) list.push({ id: v.id + 'SP', vid: v.id, license: v.licensePlate, type: 'SP', date: v.nextSP });
      if (v.nextUVV) list.push({ id: v.id + 'UVV', vid: v.id, license: v.licensePlate, type: 'UVV', date: v.nextUVV });
      if (v.nextTacho) list.push({ id: v.id + 'Tacho', vid: v.id, license: v.licensePlate, type: 'Tacho', date: v.nextTacho });
    });
    return list.sort((a, b) => {
       const [ma, ya] = a.date.split('/');
       const [mb, yb] = b.date.split('/');
       return new Date(parseInt(ya), parseInt(ma)-1).getTime() - new Date(parseInt(yb), parseInt(mb)-1).getTime();
    });
  }, [vehicles]);

  return (
    <div className="space-y-4">
      <h2 className="text-2xl font-bold text-gray-800">Anstehende Prüftermine</h2>
      <div className="bg-white rounded shadow">
        {appointments.map((apt) => (
          <div key={apt.id} className="p-4 border-b flex justify-between items-center hover:bg-gray-50">
            <div>
               <div className="font-bold">{apt.license}</div>
               <div className="text-sm text-gray-500">Typ: {apt.type}</div>
            </div>
            <div className={`font-mono font-bold ${apt.date < getTodayDate().substring(0, 7) ? 'text-red-600' : 'text-gray-800'}`}>
              {apt.date}
            </div>
          </div>
        ))}
