```typescript
class MockDB {
  private storageKey: string;

  constructor(storageKey: string) {
    this.storageKey = storageKey;
  }

  load(collection: string): any[] {
    const data = localStorage.getItem(this.storageKey);
    const parsed = data ? JSON.parse(data) : {};
    return parsed[collection] || [];
  }

  save(collection: string, data: any[]): void {
    const existing = localStorage.getItem(this.storageKey);
    const parsed = existing ? JSON.parse(existing) : {};
    parsed[collection] = data;
    localStorage.setItem(this.storageKey, JSON.stringify(parsed));
  }

  get(collection: string): any {
    return this.load(collection);
  }

  post(collection: string, data: any): { id: number; success: boolean } {
    const items = this.load(collection);
    const newId = items.length > 0 ? Math.max(...items.map((i) => i.id)) + 1 : 1;
    const newItem = { id: newId, ...data };
    this.save(collection, [...items, newItem]);
    return { id: newId, success: true };
  }

  put(collection: string, id: number, data: any): { success: boolean } {
    const items = this.load(collection);
    const index = items.findIndex((i) => i.id === id);
    if (index === -1) {
      return { success: false };
    }
    const updatedItem = { ...items[index], ...data };
    const newItems = [...items.slice(0, index), updatedItem, ...items.slice(index + 1)];
    this.save(collection, newItems);
    return { success: true };
  }

  delete(collection: string, id: number): { success: boolean } {
    const items = this.load(collection);
    const filtered = items.filter((any) => any.id !== id);
    this.save(collection, filtered);
    return { success: true };
  }
};

// --- API HELPER WITH FALLBACK ---

let isOfflineMode = false;

const api = {
  // Try server first, fallback to mockDB if fails
  request: async (method: string, endpoint: string, data: any = null) => {
    // Extract collection and ID from endpoint like "/vehicles" or "/vehicles/123"
    const parts = endpoint.split('/').filter(Boolean); // ["vehicles"] or ["vehicles", "123"]
    const collection = parts[0];
    const id = parts[1];

    // If we already know we are offline, skip fetch
    if (isOfflineMode) {
       // @ts-ignore
       if (method === 'GET') return mockDB.get(collection);
       // @ts-ignore
       if (method === 'POST') return mockDB.post(collection, data);
       // @ts-ignore
