const AppointmentsView = ({ vehicles }: any) => {
  const [filterLicense, setFilterLicense] = useState('');
  const [filterType, setFilterType] = useState('');
  const [filterMonth, setFilterMonth] = useState('');

  const appointments = useMemo(() => {
    const list: any[] = [];
    vehicles.forEach((v: Vehicle) => {
      if (v.nextHU) list.push({ id: v.id + 'HU', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'HU', date: v.nextHU });
      if (v.nextSP) list.push({ id: v.id + 'SP', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'SP', date: v.nextSP });
      if (v.nextUVV) list.push({ id: v.id + 'UVV', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'UVV', date: v.nextUVV });
      if (v.nextTacho) list.push({ id: v.id + 'Tacho', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'Tacho', date: v.nextTacho });
    });
    return list.sort((a, b) => {
       const [ma, ya] = a.date.split('/');
       const [mb, yb] = b.date.split('/');
       return new Date(parseInt(ya), parseInt(ma)-1).getTime() - new Date(parseInt(yb), parseInt(mb)-1).getTime();
    });
  }, [vehicles]);

  // Extract unique values for dropdowns
  const availableMonths = useMemo(() => {
    const months = new Set(appointments.map(a => a.date));
    return Array.from(months).sort((a: any, b: any) => {
       const [ma, ya] = a.split('/');
       const [mb, yb] = b.split('/');
       return new Date(parseInt(ya), parseInt(ma)-1).getTime() - new Date(parseInt(yb), parseInt(mb)-1).getTime();
    });
  }, [appointments]);

  const availableTypes = useMemo(() => {
      return Array.from(new Set(appointments.map(a => a.vehicleType))).sort();
  }, [appointments]);

  const filteredAppointments = appointments.filter(apt => {
    const matchLicense = apt.license.toLowerCase().includes(filterLicense.toLowerCase());
    const matchType = filterType ? apt.vehicleType === filterType : true;
    const matchMonth = filterMonth ? apt.date === filterMonth : true;
    return matchLicense && matchType && matchMonth;
  });

  const getBadgeColor = (type: string) => {
      switch(type) {
          case 'HU': return 'bg-rose-100 text-rose-800 border-rose-200';
          case 'SP': return 'bg-orange-100 text-orange-800 border-orange-200';
          case 'UVV': return 'bg-blue-100 text-blue-800 border-blue-200';
          case 'Tacho': return 'bg-purple-100 text-purple-800 border-purple-200';
          default: return 'bg-gray-100 text-gray-800';
      }
  };

  const isOverdue = (dateStr: string) => {
      const today = getTodayDate(); // YYYY-MM-DD
      const [m, y] = dateStr.split('/');
      // Compare simply by YYYY-MM string
      const aptIso = `${y}-${m.padStart(2, '0')}`;
      const todayIso = today.substring(0, 7);
      return aptIso < todayIso;
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-bold text-gray-800">Prüftermine</h2>

        {/* Filter Bar */}
        <div className="flex flex-wrap gap-2 items-center bg-white p-2 rounded shadow-sm w-full md:w-auto">
             <div className="relative">
                 <input 
                    type="text" 
                    placeholder="Kennzeichen..." 
                    className="pl-2 pr-2 py-1 border rounded text-sm w-32 focus:outline-none focus:border-blue-500"
                    value={filterLicense}
                    onChange={(e) => setFilterLicense(e.target.value)}
                 />
             </div>
             <select 
                className="border rounded py-1 px-2 text-sm focus:outline-none focus:border-blue-500 bg-white"
                value={filterType}
                onChange={(e) => setFilterType(e.target.value)}
             >
                 <option value="">Alle Typen</option>
                 {availableTypes.map((t: any) => <option key={t} value={t}>{t}</option>)}
             </select>
             <select 
                className="border rounded py-1 px-2 text-sm focus:outline-none focus:border-blue-500 bg-white"
                value={filterMonth}
                onChange={(e) => setFilterMonth(e.target.value)}
             >
                 <option value="">Alle Monate</option>
                 {availableMonths.map((m: any) => <option key={m} value={m}>{m}</option>)}
             </select>
             {(filterLicense || filterType || filterMonth) && (
                 <button 
                    onClick={() => { setFilterLicense(''); setFilterType(''); setFilterMonth(''); }}
                    className="text-gray-500 hover:text-red-500 p-1"
                    title="Filter zurücksetzen"
                 >
                     <Icons.X />
                 </button>
             )}
        </div>
      </div>

      <div className="bg-white rounded shadow overflow-hidden">
        {/* Header Row (Desktop) */}
        <div className="hidden md:flex bg-gray-50 border-b text-xs font-semibold text-gray-500 uppercase tracking-wider">
            <div className="p-3 w-32">Datum</div>
            <div className="p-3 w-32">Art</div>
            <div className="p-3 w-40">Kennzeichen</div>
            <div className="p-3 flex-1">Fahrzeugtyp</div>
        </div>

        <div className="divide-y divide-gray-100">
            {filteredAppointments.map((apt) => {
                const overdue = isOverdue(apt.date);
                return (
                  <div key={apt.id} className="p-3 flex flex-col md:flex-row md:items-center hover:bg-gray-50 transition-colors">
                    {/* Date Column */}
                    <div className="flex items-center justify-between md:block md:w-32 mb-2 md:mb-0">
                        <span className="md:hidden text-xs font-bold text-gray-500">Fällig:</span>
                        <div className={`font-mono font-bold text-lg md:text-base ${overdue ? 'text-red-600' : 'text-gray-700'}`}>
                           {apt.date}
                           {overdue && <span className="ml-2 text-xs bg-red-100 text-red-600 px-1 rounded md:hidden">Überfällig</span>}
                        </div>
                    </div>

                    {/* Badge Column */}
                    <div className="flex items-center justify-between md:block md:w-32 mb-2 md:mb-0">
                        <span className="md:hidden text-xs font-bold text-gray-500">Prüfung:</span>
                        <span className={`px-2 py-1 rounded text-xs font-bold border ${getBadgeColor(apt.inspectionType)}`}>
                            {apt.inspectionType}
                        </span>
                    </div>

                    {/* License Column */}
                    <div className="flex items-center justify-between md:block md:w-40 mb-1 md:mb-0">
                        <span className="md:hidden text-xs font-bold text-gray-500">Fahrzeug:</span>
                        <div className="font-semibold text-gray-900">{apt.license}</div>
                    </div>

                    {/* Type Column */}
                    <div className="flex items-center justify-between md:block md:flex-1">
                        <span className="md:hidden text-xs font-bold text-gray-500">Typ:</span>
                        <div className="text-sm text-gray-500">{apt.vehicleType}</div>
                    </div>
                  </div>
                );
            })}
        </div>

        {filteredAppointments.length === 0 && (
            <div className="p-8 text-center text-gray-500 flex flex-col items-center">
                <div className="opacity-20 mb-2"><Icons.Calendar /></div>
                <div>Keine Termine gefunden.</div>
            </div>
        )}
      </div>
    </div>
  );
};

