                        <input className="border p-2 rounded" placeholder="Nächste SP (MM/YYYY)" value={formData.nextSP || ''} onChange={e => setFormData({...formData, nextSP: e.target.value})} />
                    </div>
                </div>
                <div className="mt-6 flex justify-end gap-2">
                    <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">Abbrechen</button>
                    <button onClick={() => onSave(formData as Vehicle)} className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">Speichern</button>
                </div>
            </div>
        </ModalOverlay>
    );
};

const PriorityCheckbox = ({ label, checked, onChange }: any) => (
