const AppointmentsView = ({ vehicles, onComplete }: any) => {
  const appointments = useMemo(() => {
    const list: any[] = [];
    vehicles.forEach((v: Vehicle) => {
      if (v.nextHU) list.push({ id: v.id + 'HU', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'HU', date: v.nextHU });
      if (v.nextSP) list.push({ id: v.id + 'SP', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'SP', date: v.nextSP });
      if (v.nextUVV) list.push({ id: v.id + 'UVV', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'UVV', date: v.nextUVV });
      if (v.nextTacho) list.push({ id: v.id + 'Tacho', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'Tacho', date: v.nextTacho });
    });
    return list.sort((a, b) => {
       const [ma, ya] = a.date.split('/');
       const [mb, yb] = b.date.split('/');
       return new Date(parseInt(ya), parseInt(ma)-1).getTime() - new Date(parseInt(yb), parseInt(mb)-1).getTime();
    });
  }, [vehicles]);

  const getBadgeColor = (type: string) => {
      switch(type) {
          case 'HU': return 'bg-rose-100 text-rose-800 border-rose-200';
          case 'SP': return 'bg-orange-100 text-orange-800 border-orange-200';
          case 'UVV': return 'bg-blue-100 text-blue-800 border-blue-200';
          case 'Tacho': return 'bg-purple-100 text-purple-800 border-purple-200';
          default: return 'bg-gray-100 text-gray-800';
      }
  };

  const today = getTodayDate();
  const currentMonthISO = today.substring(0, 7); // YYYY-MM

  const { currentAndOverdue, upcoming } = useMemo(() => {
    const co: any[] = [];
    const up: any[] = [];

    appointments.forEach(apt => {
        const [m, y] = apt.date.split('/');
        const aptIso = `${y}-${m.padStart(2, '0')}`;

        if (aptIso <= currentMonthISO) {
            co.push({...apt, isOverdue: aptIso < currentMonthISO});
        } else {
            up.push(apt);
        }
    });
    return { currentAndOverdue: co, upcoming: up };
  }, [appointments, currentMonthISO]);

  // Group upcoming by month
  const upcomingGrouped = useMemo(() => {
      const groups: Record<string, any[]> = {};
      upcoming.forEach(apt => {
          if(!groups[apt.date]) groups[apt.date] = [];
          groups[apt.date].push(apt);
      });
      return groups;
  }, [upcoming]);

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-gray-800">Prüftermine Übersicht</h2>

      {/* SECTION 1: OVERDUE & CURRENT MONTH */}
      <div className="bg-white rounded-lg shadow-md border-t-4 border-red-500 overflow-hidden">
         <div className="bg-red-50 px-4 py-3 border-b border-red-100 flex justify-between items-center">
             <h3 className="font-bold text-red-800 text-lg flex items-center gap-2">
                 ⚠️ Fällig & Überfällig
                 <span className="bg-red-200 text-red-900 text-xs px-2 py-0.5 rounded-full">{currentAndOverdue.length}</span>
             </h3>
             <span className="text-xs text-red-600 uppercase font-semibold tracking-wider">Priorität Hoch</span>
         </div>

         <div className="divide-y divide-gray-100">
             {currentAndOverdue.length === 0 && (
                 <div className="p-8 text-center text-gray-500">Alles erledigt! Keine Prüfungen diesen Monat.</div>
             )}
             {currentAndOverdue.map(apt => (
                 <div key={apt.id} className="p-4 flex flex-col md:flex-row items-start md:items-center justify-between hover:bg-gray-50 transition-colors">
                     <div className="flex items-center gap-4 mb-2 md:mb-0">
                         <div className={`w-16 text-center font-bold text-lg leading-tight ${apt.isOverdue ? 'text-red-600' : 'text-orange-600'}`}>
                             {apt.date}
                             {apt.isOverdue && <div className="text-[10px] uppercase">Überfällig</div>}
                         </div>
                         <div>
                             <div className="font-bold text-gray-900 text-lg">{apt.license}</div>
                             <div className="text-sm text-gray-500">{apt.vehicleType}</div>
                         </div>
                     </div>

                     <div className="flex items-center gap-4 w-full md:w-auto justify-between md:justify-end">
                         <span className={`px-3 py-1 rounded text-sm font-bold border min-w-[60px] text-center ${getBadgeColor(apt.inspectionType)}`}>
                             {apt.inspectionType}
                         </span>
                         <button 
                             onClick={() => onComplete(apt)}
                             className="flex items-center gap-1 bg-green-600 hover:bg-green-700 text-white px-3 py-1.5 rounded text-sm font-medium shadow-sm transition-colors"
                         >
                             <Icons.Check /> Erledigen
                         </button>
                     </div>
                 </div>
             ))}
         </div>
      </div>

      {/* SECTION 2: UPCOMING */}
      <div>
          <h3 className="text-lg font-bold text-gray-700 mb-3 ml-1">Vorschau (Kommende Monate)</h3>
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
              {Object.keys(upcomingGrouped).length === 0 && (
                  <div className="col-span-full p-8 text-center text-gray-400 bg-white rounded border border-dashed">
                      Keine zukünftigen Termine geplant.
                  </div>
              )}
              {Object.keys(upcomingGrouped).map(dateKey => (
                  <div key={dateKey} className="bg-white rounded border border-gray-200 shadow-sm overflow-hidden">
                      <div className="bg-gray-100 px-3 py-2 font-bold text-gray-700 border-b border-gray-200 flex justify-between">
                          {dateKey}
                          <span className="text-xs font-normal bg-white px-2 rounded border">{upcomingGrouped[dateKey].length}</span>
                      </div>
                      <div className="divide-y divide-gray-100">
                          {upcomingGrouped[dateKey].map(apt => (
                              <div key={apt.id} className="p-3 flex justify-between items-center hover:bg-gray-50">
                                  <div>
                                      <div className="font-semibold text-sm">{apt.license}</div>
                                      <div className="text-xs text-gray-500">{apt.vehicleType}</div>
                                  </div>
                                  <div className="flex gap-2 items-center">
                                      <span className={`px-2 py-0.5 rounded text-[10px] font-bold border ${getBadgeColor(apt.inspectionType)}`}>
                                          {apt.inspectionType}
                                      </span>
                                      <button onClick={() => onComplete(apt)} className="text-gray-300 hover:text-green-600" title="Jetzt schon erledigen">
                                         <Icons.Check />
                                      </button>
                                  </div>
                              </div>
                          ))}
                      </div>
                  </div>
              ))}
          </div>
      </div>
    </div>
  );
};

