    // Header state
    const [header, setHeader] = useState({
        vehicleId: '',
        dateAdded: getTodayDate()
    });

    const [items, setItems] = useState<{description: string, priority: string}[]>([]);

    const groupedVehicles = useMemo(() => groupVehiclesByType(vehicles), [vehicles]);

    useEffect(() => { 
        if(isOpen) {
             if (order) {
                // Edit
                setHeader({
                    vehicleId: order.vehicleId || '',
                    dateAdded: order.dateAdded,
                });
                // Attempt to extract priority from description or default to normal
                let desc = order.description;
                let prio = 'normal';
                if(desc.includes('[Dringend]')) { prio = 'dringend'; desc = desc.replace('[Dringend]', '').trim(); }
                if(desc.includes('[Niedrig]')) { prio = 'niedrig'; desc = desc.replace('[Niedrig]', '').trim(); }

                setItems([{ description: desc, priority: prio }]);
            } else {
                // New
                setHeader({
                    vehicleId: vehicles[0]?.id || '',
                    dateAdded: getTodayDate(),
                });
                setItems([{ description: '', priority: 'normal' }]);
            }
        } 
    }, [order, isOpen, vehicles]);

    const handleSave = () => {
        const newOrders = items.map(item => {
            let desc = item.description;
            // Append priority tag if not normal, so it is visible in the list
            if(item.priority === 'dringend') desc += ' [Dringend]';
            if(item.priority === 'niedrig') desc += ' [Niedrig]';

            return {
                ...(order ? { id: order.id } : {}),
                vehicleId: header.vehicleId,
                dateAdded: header.dateAdded,
                description: desc,
                status: order ? order.status : OrderStatus.OFFEN
            };
        });

        const validOrders = newOrders.filter(o => o.description.trim() !== '');
        if(validOrders.length === 0) return;

        onSave(validOrders);
    };

    const updateItem = (index: number, field: string, value: any) => {
        const newItems = [...items];
        // @ts-ignore
        newItems[index][field] = value;
        setItems(newItems);
    };

    const removeItem = (index: number) => {
        setItems(items.filter((_, i) => i !== index));
    };

    const addItem = () => {
        setItems([...items, { description: '', priority: 'normal' }]);
    };

    return (
        <ModalOverlay isOpen={isOpen} onClose={onClose} maxWidth="max-w-4xl">
            <div className="p-6">
                <h3 className="text-xl font-bold mb-4">{order ? 'Bestellung bearbeiten' : 'Neue Bestellung'}</h3>

                {/* Header Section */}
                <div className="flex gap-4 mb-6 items-start">
                    <div className="flex flex-col gap-1 w-1/2">
                        <label className="text-sm font-bold text-gray-700">Kennzeichen</label>
                        <div className="relative border border-gray-400 p-1 rounded bg-white">
                            <select 
                                className="w-full bg-transparent outline-none appearance-none pr-4" 
                                value={header.vehicleId} 
                                onChange={e => setHeader({...header, vehicleId: e.target.value})}
                            >
                                <option value="">Wählen...</option>
                                {Object.keys(groupedVehicles).map(type => (
                                    <optgroup key={type} label={type}>
                                        {groupedVehicles[type].map(v => (
                                            <option key={v.id} value={v.id}>{v.licensePlate}</option>
                                        ))}
                                    </optgroup>
                                ))}
                            </select>
                            <span className="absolute right-2 top-1 pointer-events-none text-gray-500 text-xs">▼</span>
                        </div>
                    </div>
                    <div className="flex flex-col gap-1 w-1/2">
                        <label className="text-sm font-bold text-gray-700">Datum</label>
                        <div className="relative border border-gray-400 p-1 rounded bg-white">
                             <input 
                                type="date"
                                className="w-full bg-transparent outline-none" 
                                value={header.dateAdded} 
                                onChange={e => setHeader({...header, dateAdded: e.target.value})} 
                             />
                        </div>
                    </div>
                </div>

                {/* Items List */}
                <div className="space-y-3 max-h-[50vh] overflow-y-auto pr-1">
                    {items.map((item, idx) => (
                        <div key={idx} className="flex gap-2 items-start group">
                            <div className="border border-gray-400 p-3 flex-1 rounded bg-white shadow-sm">
                                <input 
                                    className="w-full border-b border-gray-300 pb-1 mb-2 outline-none focus:border-blue-500" 
                                    placeholder="Artikel / Beschreibung" 
                                    value={item.description} 
                                    onChange={e => updateItem(idx, 'description', e.target.value)} 
                                />
                                <div className="flex gap-3 items-center text-sm">
                                    <span className="font-bold text-gray-600 mr-1">Priorität:</span>
                                    <PriorityCheckbox 
                                        label="normal" 
                                        checked={item.priority === 'normal'} 
                                        onChange={() => updateItem(idx, 'priority', 'normal')} 
                                    />
                                    <PriorityCheckbox 
                                        label="dringend" 
                                        checked={item.priority === 'dringend'} 
                                        onChange={() => updateItem(idx, 'priority', 'dringend')} 
                                    />
                                    <PriorityCheckbox 
                                        label="niedrig" 
                                        checked={item.priority === 'niedrig'} 
                                        onChange={() => updateItem(idx, 'priority', 'niedrig')} 
                                    />
                                </div>
                            </div>
                            {items.length > 1 && (
                                <button onClick={() => removeItem(idx)} className="mt-4 text-gray-400 hover:text-red-600 transition-colors">
                                    <Icons.Trash />
                                </button>
                            )}
                        </div>
                    ))}
                </div>

                <button onClick={addItem} className="w-full border-2 border-dashed border-gray-300 text-gray-500 py-2 mt-4 text-sm font-bold hover:bg-gray-50 hover:border-gray-400 hover:text-gray-700 transition-colors rounded">
                    Neue Bestellung hinzufügen
                </button>

                <div className="mt-8 flex justify-end">
                    <button onClick={() => handleSave()} className="border border-gray-400 px-6 py-2 bg-white hover:bg-gray-100 font-bold rounded shadow-sm text-gray-800">
                        Speichern
                    </button>
                </div>
            </div>
        </ModalOverlay>
    );
};

// --- MAIN APPLICATION ---

const App = () => {
  const [activeTab, setActiveTab] = useState('todo');

  // App Data State
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);

  // Instead of blocking error, we track if we are offline
  const [appIsOffline, setAppIsOffline] = useState(false);

  // Admin Mode
  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');

  // Modals
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [editingVehicle, setEditingVehicle] = useState<Vehicle | null>(null);

  const [showEntryModal, setShowEntryModal] = useState(false);
  const [editingEntry, setEditingEntry] = useState<LogEntry | null>(null);

  const [showOrderModal, setShowOrderModal] = useState(false);
  const [editingOrder, setEditingOrder] = useState<Order | null>(null);

  const [showInspectionCompleteModal, setShowInspectionCompleteModal] = useState(false);
  // Unified state for completing either a LogEntry or a direct Calendar item
  const [completingInspection, setCompletingInspection] = useState<{
      vehicleId: string, 
      type: string, 
      logId?: string, // If it comes from a specific log task
      newDate: string 
  } | null>(null);

  // --- DATA LOADING ---
  const refreshData = useCallback(async () => {
    setLoading(true);
    try {
      // Force checking backend first time, or continue offline if set
      const vData = await api.get('/vehicles');
      const lData = await api.get('/logs');
      const oData = await api.get('/orders');

      setVehicles(vData);
      setLogs(lData);
      setOrders(oData);

      // Update UI state based on api internal flag
      setAppIsOffline(isOfflineMode);
    } catch (e: any) {
      console.error("Critical Error", e);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refreshData();
  }, [refreshData]);

  const handleAdminLogin = () => {
    if (adminPassword === 'Co33ing#admin') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setAdminPassword('');
    } else {
      alert('Falsches Passwort!');
    }
  };

  // --- LOGIC: VEHICLE ---
  const handleSaveVehicle = async (v: Vehicle) => {
    try {
      // Coupling Logic Check
      if (v.type === VehicleType.LKW && v.coupledVehicleId) {
        const existingCoupling = vehicles.find(
          other => other.id !== v.id && other.type === VehicleType.LKW && other.coupledVehicleId === v.coupledVehicleId
        );
        if (existingCoupling) {
          if (!window.confirm(`Der Auflieger ist bereits mit ${existingCoupling.licensePlate} gekoppelt. Verbindung lösen?`)) return;
          // Uncouple old
          await api.put(`/vehicles/${existingCoupling.id}`, { ...existingCoupling, coupledVehicleId: null });
        }
      }

      if (v.id) {
        await api.put(`/vehicles/${v.id}`, v);
      } else {
        await api.post('/vehicles', v);
      }
      refreshData();
      setShowVehicleModal(false);
      setEditingVehicle(null);
    } catch (e: any) {
      alert(`Fehler beim Speichern: ${e.message}`);
    }
  };

  const deleteVehicle = async (id: string) => {
    if (confirm('Fahrzeug wirklich löschen?')) {
      try {
        await api.delete(`/vehicles/${id}`);
        refreshData();
      } catch (e: any) {
        alert(`Löschen fehlgeschlagen: ${e.message}`);
      }
    }
  };

  // --- LOGIC: ENTRIES ---
  const handleSaveEntries = async (entries: Partial<LogEntry>[]) => {
    try {
      // Process serially or parallel
      for (const entry of entries) {
        if (entry.id) {
          await api.put(`/logs/${entry.id}`, entry);
        } else {
          await api.post('/logs', entry);
        }
      }
      refreshData();
      setShowEntryModal(false);
      setEditingEntry(null);
    } catch (e: any) {
      alert(`Fehler beim Speichern: ${e.message}`);
    }
  };

  // Called from Dashboard (LogEntry)
  const handleCompleteEntry = async (entry: LogEntry) => {
    if (entry.type === EntryType.PRUEFUNG && entry.inspectionType) {
      setCompletingInspection({ 
          vehicleId: entry.vehicleId, 
          type: entry.inspectionType, 
          logId: entry.id,
          newDate: '' 
      });
      setShowInspectionCompleteModal(true);
    } else {
      try {
        await api.put(`/logs/${entry.id}`, { ...entry, status: 'DONE', dateCompleted: getTodayDate() });
        refreshData();
      } catch (e: any) {
        alert(`Fehler beim Abschließen: ${e.message}`);
      }
    }
  };

  // Called from Appointments Calendar (Virtual Item)
  const handleCompleteInspection = async (item: any) => {
      setCompletingInspection({
          vehicleId: item.vid,
          type: item.inspectionType,
          logId: undefined, // No existing log entry
          newDate: ''
      });
      setShowInspectionCompleteModal(true);
  };

  const confirmInspectionCompletion = async () => {
    if (!completingInspection || !isValidDateMMYYYY(completingInspection.newDate)) {
      alert('Bitte gültiges Datum (MM/YYYY) eingeben!');
      return;
    }
    const { vehicleId, type, logId, newDate } = completingInspection;

    try {
      // 1. Update Vehicle Date
      const vehicle = vehicles.find(v => v.id === vehicleId);
      if (vehicle) {
        const updates: any = {};
        if (type === 'HU') updates.nextHU = newDate;
        if (type === 'SP') updates.nextSP = newDate;
        if (type === 'UVV') updates.nextUVV = newDate;
        if (type === 'Tacho') updates.nextTacho = newDate;

        await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, ...updates });
      }

      // 2. Handle Log Entry
      if (logId) {
          // If we are completing an existing task
          const existingLog = logs.find(l => l.id === logId);
          if (existingLog) {
            await api.put(`/logs/${logId}`, { ...existingLog, status: 'DONE', dateCompleted: getTodayDate() });
          }
      } else {
          // If we came from the calendar, create a history entry
          await api.post('/logs', {
              vehicleId: vehicleId,
              type: EntryType.PRUEFUNG,
              description: `${type} erledigt (Neu: ${newDate})`,
              priority: Priority.NORMAL,
              dateAdded: getTodayDate(), // Or maybe today?
              dateCompleted: getTodayDate(),
              status: 'DONE',
              inspectionType: type
          });
      }

      refreshData();
      setShowInspectionCompleteModal(false);
      setCompletingInspection(null);
    } catch (e: any) {
      alert(`Fehler: ${e.message}`);
    }
  };

  const deleteLog = async (id: string, skipConfirm = false) => {
    if (skipConfirm || confirm('Eintrag löschen?')) {
      try {
        await api.delete(`/logs/${id}`);
        refreshData();
      } catch (e: any) {
        alert(`Löschen fehlgeschlagen: ${e.message}`);
      }
    }
  };

  // --- LOGIC: ORDERS ---
  const handleSaveOrders = async (ordersList: Partial<Order>[]) => {
    try {
      for (const formData of ordersList) {
        if (formData.id) {
            await api.put(`/orders/${formData.id}`, formData);
        } else {
            await api.post('/orders', formData);
        }
      }
      refreshData();
      setShowOrderModal(false);
      setEditingOrder(null);
    } catch (e: any) { alert(`Fehler beim Speichern: ${e.message}`); }
  };

  const updateOrderStatus = async (id: string, status: OrderStatus) => {
    const order = orders.find(o => o.id === id);
    if(order) {
        try {
          await api.put(`/orders/${id}`, { ...order, status });
          refreshData();
        } catch (e: any) {
          alert(`Fehler beim Aktualisieren: ${e.message}`);
        }
    }
  };

  const deleteOrder = async (id: string, skipConfirm: boolean = false) => {
    if(!skipConfirm && !confirm('Bestellung wirklich löschen?')) return;
    try {
      await api.delete(`/orders/${id}`);
      refreshData();
    } catch (e: any) {
      alert(`Löschen fehlgeschlagen: ${e.message}`);
    }
  }

  // --- RENDER ---

  if (loading && vehicles.length === 0) {
    return <div className="flex h-screen items-center justify-center">Lade Daten...</div>;
  }

  return (
    <div className="flex h-screen flex-col md:flex-row font-sans">
      {/* SIDEBAR NAVIGATION */}
      <div className="w-full md:w-64 bg-slate-800 text-white flex-shrink-0 flex flex-col no-print">
        <div className="p-4 font-bold text-xl border-b border-slate-700">Fuhrpark Manager</div>
        <nav className="flex-1 p-2 space-y-1">
          {[
            { id: 'todo', label: 'ToDo', icon: Icons.Dashboard },
            { id: 'termine', label: 'Prüftermine', icon: Icons.Calendar },
            { id: 'bestellungen', label: 'Bestellliste', icon: Icons.ShoppingCart },
            { id: 'fahrzeuge', label: 'Fahrzeugstamm', icon: Icons.Truck },
            { id: 'historie', label: 'Historie & Suche', icon: Icons.History },
          ].map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded text-left transition-colors ${activeTab === item.id ? 'bg-primary text-white' : 'text-slate-300 hover:bg-slate-700'}`}
            >
              <item.icon />
              {item.label}
            </button>
          ))}
        </nav>

        {/* OFFLINE INDICATOR */}
        {appIsOffline && (
           <div className="p-3 bg-amber-600 text-white text-xs font-bold flex items-center gap-2 mx-2 mb-2 rounded">
             <Icons.WifiOff />
             <div>
               Offline Modus
               <div className="font-normal opacity-75 text-[10px]">Daten werden im Browser gespeichert.</div>
             </div>
           </div>
        )}

        <div className="p-4 border-t border-slate-700 text-xs text-slate-500 flex justify-between items-center">
          <span>v2.7 (Update)</span>
          <button onClick={() => setShowAdminLogin(true)} className="opacity-50 hover:opacity-100">
            <Icons.Lock />
          </button>
        </div>
      </div>

      {/* MAIN CONTENT AREA */}
      <main className="flex-1 overflow-auto bg-gray-50 p-4 md:p-8 relative">

        {/* --- DASHBOARD --- */}
        {activeTab === 'todo' && (
          <DashboardView 
            logs={logs} 
            vehicles={vehicles} 
            onComplete={handleCompleteEntry}
            onEdit={(l: LogEntry) => { setEditingEntry(l); setShowEntryModal(true); }}
            onDelete={deleteLog}
            onAdd={() => { setEditingEntry(null); setShowEntryModal(true); }}
          />
        )}

        {/* --- FAHRZEUGE --- */}
        {activeTab === 'fahrzeuge' && (
          <VehicleListView 
            vehicles={vehicles} 
            onEdit={(v: Vehicle) => { setEditingVehicle(v); setShowVehicleModal(true); }}
            onDelete={deleteVehicle}
            onAdd={() => { setEditingVehicle(null); setShowVehicleModal(true); }}
          />
        )}

        {/* --- TERMINE --- */}
        {activeTab === 'termine' && (
          <AppointmentsView 
            vehicles={vehicles} 
            onComplete={handleCompleteInspection}
          />
        )}

        {/* --- BESTELLUNGEN --- */}
        {activeTab === 'bestellungen' && (
          <OrdersView 
            orders={orders} 
            vehicles={vehicles}
            onAdd={() => { setEditingOrder(null); setShowOrderModal(true); }}
            onEdit={(o: Order) => { setEditingOrder(o); setShowOrderModal(true); }}
            onStatusChange={updateOrderStatus}
            onDelete={deleteOrder}
          />
        )}

        {/* --- HISTORIE --- */}
        {activeTab === 'historie' && (
          <HistoryView 
            logs={logs} 
            vehicles={vehicles} 
            isAdmin={isAdmin}
            onEdit={(l: LogEntry) => { setEditingEntry(l); setShowEntryModal(true); }}
            onDelete={deleteLog}
          />
        )}

      </main>

      {/* --- MODALS --- */}

      {/* Vehicle Modal */}
      {showVehicleModal && (
        <VehicleModal 
          isOpen={showVehicleModal} 
          onClose={() => setShowVehicleModal(false)}
          vehicle={editingVehicle}
          allVehicles={vehicles}
          onSave={handleSaveVehicle}
        />
      )}

      {/* Entry Modal */}
      {showEntryModal && (
        <EntryModal 
          isOpen={showEntryModal}
          onClose={() => setShowEntryModal(false)}
          entry={editingEntry}
          vehicles={vehicles}
          onSave={handleSaveEntries}
          onDelete={deleteLog}
        />
      )}

      {/* Order Modal */}
      {showOrderModal && (
        <OrderModal
          isOpen={showOrderModal}
          onClose={() => setShowOrderModal(false)}
          order={editingOrder}
          onSave={handleSaveOrders}
          vehicles={vehicles}
        />
      )}

      {/* Inspection Complete Modal */}
      {showInspectionCompleteModal && (
          <ModalOverlay isOpen={showInspectionCompleteModal} onClose={() => setShowInspectionCompleteModal(false)}>
              <div className="p-6">
                  <h3 className="text-xl font-bold mb-4 flex items-center gap-2">
                     <Icons.Check /> Prüfung erledigt
                  </h3>

                  <div className="mb-6 bg-blue-50 border border-blue-100 p-4 rounded text-blue-900">
                      <p className="font-bold">{completingInspection?.type} für dieses Fahrzeug abschließen</p>
                      <p className="text-sm mt-1">Bitte geben Sie den nächsten Fälligkeitstermin ein. Dieser wird in den Fahrzeugstamm übernommen.</p>
                  </div>

                  <label className="block text-sm font-bold text-gray-700 mb-1">
                      Neuer Termin (Pflichtfeld)
                  </label>
                  <input 
                    type="text" 
                    placeholder="MM/YYYY" 
                    className="border-2 border-blue-500 p-3 rounded w-full font-mono text-xl text-center focus:outline-none focus:ring-2 focus:ring-blue-300"
                    value={completingInspection?.newDate || ''}
                    onChange={(e) => setCompletingInspection(prev => prev ? ({...prev, newDate: e.target.value}) : null)}
                    autoFocus
                  />
                  <div className="text-xs text-gray-400 mt-1 text-center">Format: Monat / Jahr (z.B. 08/2026)</div>

                  <div className="mt-8 flex justify-end gap-3">
                       <button onClick={() => setShowInspectionCompleteModal(false)} className="px-5 py-2 bg-gray-100 hover:bg-gray-200 rounded text-gray-700 font-medium">Abbrechen</button>
                       <button onClick={confirmInspectionCompletion} className="px-5 py-2 bg-green-600 hover:bg-green-700 text-white rounded font-bold shadow-lg transform active:scale-95 transition-all">
                           Speichern & Abschließen
                       </button>
                  </div>
              </div>
          </ModalOverlay>
      )}

    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { createRoot } from 'react-dom/client';

// --- TYPES & ENUMS ---

enum VehicleType {
  PKW = 'PKW',
  LKW = 'LKW',
  AUFLIEGER = 'Auflieger',
  ANHAENGER = 'Anhänger',
  MASCHINE = 'Maschine',
}

enum EntryType {
  REPARATUR = 'Reparatur',
  WARTUNG = 'Wartung',
  PRUEFUNG = 'Prüfung',
}

enum Priority {
  LOW = 'Niedrig',
  NORMAL = 'Normal',
  HIGH = 'Dringend',
}

enum OrderStatus {
  OFFEN = 'Offen',
  BESTELLT = 'Bestellt',
  ERLEDIGT = 'Erledigt',
}

interface Attachment {
  name: string;
  data: string; // Base64
  type: string;
}

interface Vehicle {
  id: string;
  licensePlate: string;
  type: VehicleType;
  manufacturer: string;
  model: string; // Typ
  vin: string;
  year: number;
  notes: string;
  coupledVehicleId?: string | null; // For LKW <-> Auflieger

  // Inspection Due Dates (MM/YYYY)
  nextHU?: string;
  nextSP?: string;
  nextUVV?: string;
  nextTacho?: string;

  currentMileage?: number; // KM or Hours
}

interface LogEntry {
  id: string;
  vehicleId: string;
  type: EntryType;
  description: string;
  priority: Priority;
  dateAdded: string; // ISO Date
  dateCompleted?: string;
  status: 'OPEN' | 'DONE';
  mileage?: number;

  // Specific for inspections
  inspectionType?: 'HU' | 'SP' | 'UVV' | 'Tacho';

  // Attachments
  attachments?: Attachment[];
}

interface Order {
  id: string;
  description: string;
  vehicleId?: string;
  dateAdded: string;
  status: OrderStatus;
}

// --- ICONS ---

const Icons = {
  Dashboard: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>,
