const AppointmentsView = ({ vehicles, onComplete }: any) => {
  const [selectedMonth, setSelectedMonth] = useState(getTodayDate().substring(0, 7));

  const appointments = useMemo(() => {
    const list: any[] = [];
    vehicles.forEach((v: Vehicle) => {
      if (v.nextHU) list.push({ id: v.id + 'HU', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'HU', date: v.nextHU });
      if (v.nextSP) list.push({ id: v.id + 'SP', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'SP', date: v.nextSP });
      if (v.nextUVV) list.push({ id: v.id + 'UVV', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'UVV', date: v.nextUVV });
      if (v.nextTacho) list.push({ id: v.id + 'Tacho', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'Tacho', date: v.nextTacho });
    });
    return list.sort((a, b) => {
       const [ma, ya] = a.date.split('/');
       const [mb, yb] = b.date.split('/');
       return new Date(parseInt(ya), parseInt(ma)-1).getTime() - new Date(parseInt(yb), parseInt(mb)-1).getTime();
    });
  }, [vehicles]);

  const getBadgeColor = (type: string) => {
      switch(type) {
          case 'HU': return 'bg-rose-100 text-rose-800 border-rose-200';
          case 'SP': return 'bg-orange-100 text-orange-800 border-orange-200';
          case 'UVV': return 'bg-blue-100 text-blue-800 border-blue-200';
          case 'Tacho': return 'bg-purple-100 text-purple-800 border-purple-200';
          default: return 'bg-gray-100 text-gray-800';
      }
  };

  const { overdue, dueThisMonth, upcoming } = useMemo(() => {
    const ov: any[] = [];
    const curr: any[] = [];
    const up: any[] = [];

    appointments.forEach(apt => {
        const [m, y] = apt.date.split('/');
        const aptIso = `${y}-${m.padStart(2, '0')}`;

        // Strict logic for visibility:
        // Overdue: Strictly older than the selected month
        // Current: Exactly the selected month
        // Upcoming: Strictly future compared to selected month

        if (aptIso < selectedMonth) {
            ov.push({...apt, isOverdue: true});
        } else if (aptIso === selectedMonth) {
            curr.push({...apt, isOverdue: false});
        } else {
            up.push(apt);
        }
    });
    return { overdue: ov, dueThisMonth: curr, upcoming: up };
  }, [appointments, selectedMonth]);

  // Group upcoming by month
  const upcomingGrouped = useMemo(() => {
      const groups: Record<string, any[]> = {};
      upcoming.forEach(apt => {
          if(!groups[apt.date]) groups[apt.date] = [];
          groups[apt.date].push(apt);
      });
      return groups;
  }, [upcoming]);

  const AppointmentCard = ({ apt, isOverdue }: any) => (
      <div className={`bg-white rounded-lg shadow-sm border-l-8 overflow-hidden relative ${isOverdue ? 'border-red-600 bg-red-50' : 'border-blue-400'}`}>
         <div className="p-4">
             <div className="flex justify-between items-start mb-2">
                 <span className={`inline-block px-2 py-1 rounded text-xs font-bold uppercase tracking-wider ${isOverdue ? 'bg-red-600 text-white' : 'bg-blue-100 text-blue-800'}`}>
                     {isOverdue ? 'ÜBERFÄLLIG' : 'Diesen Monat'}
                 </span>
                 <span className={`font-mono font-bold text-lg ${isOverdue ? 'text-red-700' : 'text-blue-600'}`}>{apt.date}</span>
             </div>

             <div className="mb-4">
                 <div className="text-2xl font-bold text-gray-800">{apt.license}</div>
                 <div className="text-sm text-gray-500">{apt.vehicleType}</div>
             </div>

             <div className="flex items-center justify-between mt-4 pt-4 border-t border-gray-100">
                 <span className={`px-3 py-1 rounded text-sm font-bold border ${getBadgeColor(apt.inspectionType)}`}>
                     {apt.inspectionType}
                 </span>
                 <button 
                     onClick={() => onComplete(apt)}
                     className={`flex items-center gap-2 text-white px-4 py-2 rounded shadow transition-colors text-sm font-bold ${isOverdue ? 'bg-red-600 hover:bg-red-700' : 'bg-slate-800 hover:bg-slate-900'}`}
                 >
                     <Icons.Check />
                     Prüfung erledigen
                 </button>
             </div>
         </div>
     </div>
  );

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row md:items-end justify-between border-b pb-4 gap-4">
          <div>
            <h2 className="text-2xl font-bold text-gray-800">Prüfungs-Monitor</h2>
            <div className="text-sm text-gray-500 mt-1">
                Anzeige für: <span className="font-mono font-bold text-gray-700">{selectedMonth}</span>
            </div>
          </div>

          <div className="flex items-center gap-2 bg-white p-2 rounded border shadow-sm">
             <span className="text-sm font-bold text-gray-600">Monat wählen:</span>
             <input 
                type="month" 
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="border border-gray-300 rounded px-2 py-1 text-sm font-sans focus:outline-none focus:ring-2 focus:ring-blue-500"
             />
             {selectedMonth !== getTodayDate().substring(0, 7) && (
                 <button 
                    onClick={() => setSelectedMonth(getTodayDate().substring(0, 7))}
                    className="ml-2 text-xs bg-blue-100 text-blue-700 px-2 py-1.5 rounded font-bold hover:bg-blue-200 transition-colors"
                    title="Zurück zum aktuellen Monat"
                 >
                    Heute
                 </button>
             )}
          </div>
      </div>

      {/* SECTION 1: OVERDUE (Always visible if exists) */}
      {overdue.length > 0 && (
          <div className="space-y-4 animate-pulse-once">
              <h3 className="font-bold text-red-700 text-lg flex items-center gap-2 bg-red-100 p-3 rounded border border-red-200">
                  <Icons.Alert />
                  ÜBERFÄLLIGE PRÜFUNGEN ({overdue.length})
                  <span className="text-sm font-normal text-red-800 ml-auto">Aus Vormonaten (vor {selectedMonth})</span>
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                  {overdue.map(apt => (
                      <AppointmentCard key={apt.id} apt={apt} isOverdue={true} />
                  ))}
              </div>
          </div>
      )}

      {/* SECTION 2: CURRENT MONTH */}
      <div className="space-y-4">
          <h3 className="font-bold text-blue-800 text-lg flex items-center gap-2 border-b border-blue-200 pb-2">
              <Icons.Calendar />
              FÄLLIG IM {selectedMonth} ({dueThisMonth.length})
          </h3>

          {dueThisMonth.length === 0 && (
             <div className="bg-blue-50 border border-blue-100 text-blue-800 p-8 rounded-lg text-center">
                 <div className="text-3xl mb-2">📅</div>
                 <div className="font-bold">Diesen Monat nichts geplant</div>
                 <div className="text-sm opacity-75">Für {selectedMonth} stehen keine regulären Prüfungen an.</div>
             </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
             {dueThisMonth.map(apt => (
                 <AppointmentCard key={apt.id} apt={apt} isOverdue={false} />
             ))}
          </div>
      </div>

      {/* SECTION 3: FORECAST */}
      <div className="pt-8 border-t mt-8">
          <h3 className="text-lg font-bold text-gray-600 mb-4 uppercase tracking-wider">Vorschau (Nach {selectedMonth})</h3>

          <div className="space-y-6">
              {Object.keys(upcomingGrouped).length === 0 && (
                  <div className="text-gray-400 italic">Keine späteren Termine geplant.</div>
              )}
              {Object.keys(upcomingGrouped).map(dateKey => (
                  <div key={dateKey} className="flex flex-col md:flex-row gap-4 md:items-start group">
                      <div className="md:w-32 flex-shrink-0 pt-2">
                          <div className="font-bold text-gray-700 text-lg bg-gray-100 inline-block px-3 py-1 rounded border border-gray-200">
                              {dateKey}
                          </div>
                      </div>
                      <div className="flex-1 bg-white border border-gray-200 rounded-lg shadow-sm divide-y divide-gray-100">
                          {upcomingGrouped[dateKey].map(apt => (
                              <div key={apt.id} className="p-3 flex justify-between items-center hover:bg-gray-50 transition-colors">
                                  <div className="flex items-center gap-4">
                                      <div className={`w-12 text-center text-xs font-bold px-1 py-0.5 rounded border ${getBadgeColor(apt.inspectionType)}`}>
                                          {apt.inspectionType}
                                      </div>
                                      <div>
                                          <div className="font-bold text-gray-800">{apt.license}</div>
                                          <div className="text-xs text-gray-500">{apt.vehicleType}</div>
                                      </div>
                                  </div>
                                  <button onClick={() => onComplete(apt)} className="text-gray-300 hover:text-green-600 p-2" title="Jetzt schon erledigen">
                                     <Icons.Check />
                                  </button>
                              </div>
                          ))}
                      </div>
                  </div>
              ))}
          </div>
      </div>
    </div>
  );
};

