// --- TYPES & ENUMS ---

enum VehicleType {
  PKW = 'PKW',
  LKW = 'LKW',
  TRANSPORTER = 'Transporter',
  ANHAENGER = 'Anhänger',
  AUFLIEGER = 'Auflieger',
  SONSTIGE = 'Sonstige',
  MASCHINE = 'Maschine'
}

enum EntryType {
  REPARATUR = 'Reparatur',
  WARTUNG = 'Wartung',
  PRUEFUNG = 'Prüfung',
}

enum Priority {
  LOW = 'Niedrig',
  NORMAL = 'Normal',
  HIGH = 'Dringend',
}

enum OrderStatus {
  OFFEN = 'Offen',
  BESTELLT = 'Bestellt',
  ERLEDIGT = 'Erledigt',
}

interface Attachment {
  name: string;
  data: string; // Base64
  type: string;
}

interface Vehicle {
  id: string;
  licensePlate: string;
  type: VehicleType | string;
  manufacturer: string;
  model: string; // Typ
  vin: string;
  year: number;
  notes: string;
  coupledVehicleId?: string | null; // For LKW <-> Auflieger

  // Inspection Due Dates (MM/YYYY)
  nextHU?: string;
  nextSP?: string;
  nextUVV?: string;
  nextTacho?: string;

  currentMileage?: number; // KM or Hours
}

interface LogEntry {
  id: string;
  vehicleId: string;
  type: EntryType;
  description: string;
  priority: Priority;
  dateAdded: string; // ISO Date
  dateCompleted?: string;
  status: 'OPEN' | 'DONE';
  mileage?: number;

  // Specific for inspections
  inspectionType?: 'HU' | 'SP' | 'UVV' | 'Tacho';

  // Attachments
  attachments?: Attachment[];
}

interface Order {
  id: string;
  description: string;
  vehicleId?: string;
  dateAdded: string;
  status: OrderStatus;
}

